import{p as e,x as t}from"./index-bwCkIPCv.js";var n=e(`FileText`,[[`path`,{d:`M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z`,key:`1rqfz7`}],[`path`,{d:`M14 2v4a2 2 0 0 0 2 2h4`,key:`tnqrlb`}],[`path`,{d:`M10 9H8`,key:`b1mrlr`}],[`path`,{d:`M16 13H8`,key:`t4e002`}],[`path`,{d:`M16 17H8`,key:`z1uh3a`}]]),r=JSON.parse('[{"id":"getting-started","title":{"en":"Get started","ar":"البدء مع المنصة"},"description":{"en":"Understand the platform, create an account, and launch your first project.","ar":"تعرّف على المنصة وأنشئ حسابك وجهّز مشروعك الأول."},"articles":[{"id":"overview","title":{"en":"VELTNEX overview","ar":"التعرّف على VELTNEX"},"summary":{"en":"Understand hosting, managed services, projects, and environments.","ar":"تعرّف على الاستضافة والخدمات الجاهزة والمشاريع وبيئات العمل."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"concepts","title":{"en":"Core concepts","ar":"المفاهيم الأساسية"},"blocks":[{"type":"paragraph","text":{"en":"VELTNEX provides managed Odoo infrastructure and a customer control panel. Hosting subscriptions give you database and developer tools. Ready-made services provide a configured application with a more limited management interface. Available plans, regions, versions, and services depend on the platform catalog.","ar":"توفّر VELTNEX بنية استضافة مُدارة لتطبيق Odoo ولوحة تحكم للعميل. تتيح اشتراكات الاستضافة إدارة قواعد البيانات وأدوات التطوير، بينما تقدّم الخدمات الجاهزة تطبيقًا مُعدًّا مسبقًا بواجهة إدارة أبسط. تتحدد الخطط والمناطق والإصدارات والخدمات المتاحة حسب كتالوج المنصة."}},{"type":"table","headers":[{"en":"Concept","ar":"المفهوم"},{"en":"Meaning","ar":"المقصود"}],"rows":[[{"en":"Project","ar":"المشروع"},{"en":"A hosting workspace anchored by its Production instance.","ar":"مساحة عمل للاستضافة ترتبط بـ Instance الخاصة ببيئة Production."}],[{"en":"Instance","ar":"Instance"},{"en":"A running application environment with its resources, address, and data.","ar":"بيئة تشغيل للتطبيق لها مواردها وعنوانها وبياناتها."}],[{"en":"Production","ar":"Production"},{"en":"The main environment used for live business data.","ar":"البيئة الرئيسية لبيانات العمل الفعلية."}],[{"en":"Staging / Development","ar":"Staging / Development"},{"en":"Separate environments and Git branches within the same hosting project.","ar":"بيئات وفروع Git مستقلة داخل مشروع الاستضافة نفسه."}]]}]},{"id":"responsibilities","title":{"en":"Your responsibilities","ar":"مسؤولياتك"},"blocks":[{"type":"paragraph","text":{"en":"Use the control panel to manage infrastructure, access, billing, and recovery. Configure business users and application permissions inside Odoo separately. Keep your own recoverable backup before destructive changes. Hosting an Enterprise image does not replace your Odoo Enterprise license.","ar":"استخدم لوحة التحكم لإدارة البنية والصلاحيات والفوترة والاستعادة. أما مستخدمو التطبيق وصلاحياتهم فتُدار داخل Odoo بشكل مستقل. احتفظ بنسخة قابلة للاستعادة قبل أي تغيير يحذف البيانات أو يستبدلها. استضافة إصدار Enterprise لا تُغني عن ترخيص Odoo Enterprise."}}]}],"related":["launch-instance","project-workspace","iam-overview"],"sources":["control-plane/saas_website/controllers/api.py","frontend/veltnex/src/pages/portal/Environments.tsx"]},{"id":"create-account","title":{"en":"Create an account","ar":"إنشاء حساب"},"summary":{"en":"Register with your own email and mobile number.","ar":"سجّل ببريدك الإلكتروني ورقم هاتفك."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before you begin","ar":"قبل البدء"},"blocks":[{"type":"paragraph","text":{"en":"You need an email address, a mobile number, a country and city, and a password of at least 8 characters. Login identifiers and phone numbers are checked against existing accounts, including inactive accounts. A historical contact without a login does not by itself reserve your details.","ar":"تحتاج إلى بريد إلكتروني ورقم هاتف ودولة ومدينة، وكلمة مرور لا تقل عن 8 أحرف. تتحقق المنصة من عدم استخدام بيانات تسجيل الدخول ورقم الهاتف في حساب آخر، بما في ذلك الحسابات غير النشطة. وجود جهة اتصال قديمة دون حساب دخول لا يمنع التسجيل بهذه البيانات."}}]},{"id":"steps","title":{"en":"Register","ar":"خطوات التسجيل"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open **Get started** or **Sign in → Create an account**.","ar":"افتح **ابدأ الآن** أو **تسجيل الدخول ← إنشاء حساب**."},{"en":"Enter your details and select your country. Check the phone country code before requesting a code.","ar":"أدخل بياناتك واختر الدولة، وتأكد من مفتاح الاتصال قبل طلب رمز التحقق."},{"en":"Request the WhatsApp code and enter it on the verification screen. Use the newest code after resending.","ar":"اطلب رمز WhatsApp وأدخله في صفحة التحقق. إذا طلبت رمزًا جديدًا فاستخدم الرمز الأخير."},{"en":"Continue to the hosting configurator or your dashboard after registration succeeds.","ar":"بعد نجاح التسجيل، تابع إلى إعداد الاستضافة أو لوحة التحكم."}]}]},{"id":"troubleshoot","title":{"en":"If registration fails","ar":"إذا تعذّر التسجيل"},"blocks":[{"type":"paragraph","text":{"en":"Review email spelling, the international phone format, country, city, and password length. The duplicate-details message intentionally does not disclose another account. Try password recovery if you may already have registered; otherwise contact support with the error and time, without sending your password or verification code. WhatsApp delivery requires the platform to configure its provider.","ar":"راجع كتابة البريد وصيغة رقم الهاتف الدولية والدولة والمدينة وطول كلمة المرور. رسالة تكرار البيانات لا تكشف معلومات حساب آخر. جرّب استعادة كلمة المرور إذا سبق لك التسجيل، وإلا أرسل للدعم نص الخطأ ووقت ظهوره دون كلمة المرور أو رمز التحقق. يتطلب إرسال رموز WhatsApp إعداد مزوّد الخدمة من جانب المنصة."}}]}],"related":["password-recovery","teammate-onboarding"],"sources":["control-plane/saas_website/controllers/api.py","control-plane/saas_iam/controllers/api.py"]},{"id":"launch-instance","title":{"en":"Launch your first hosting project","ar":"إطلاق مشروع الاستضافة الأول"},"summary":{"en":"Configure a subscription, complete checkout, and initialize your data.","ar":"حدّد اشتراكك وأكمل الدفع ثم جهّز قاعدة بياناتك."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before you begin","ar":"قبل البدء"},"blocks":[{"type":"paragraph","text":{"en":"Sign in with a fully set-up account. Choose a compatible Odoo version and edition, a region, and a plan. The quotation and checkout show current prices; this documentation does not fix prices or promise a provisioning duration.","ar":"سجّل الدخول بحساب مكتمل الإعداد، واختر إصدار Odoo ونسخته والمنطقة والخطة المناسبة. يعرض التسعير وصفحة الدفع الأسعار الحالية؛ ولا تحدد هذه الوثائق أسعارًا ثابتة أو مدة مضمونة للتجهيز."}}]},{"id":"steps","title":{"en":"Configure and launch","ar":"الإعداد والإطلاق"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open **Hosting**, select a plan or custom size, and enter a project name and available subdomain.","ar":"افتح **الاستضافة**، واختر خطة أو موارد مخصصة، ثم أدخل اسم المشروع ونطاقًا فرعيًا متاحًا."},{"en":"Select the Odoo version, region, Workers, storage, billing period, and optional add-ons shown in the configurator.","ar":"حدّد إصدار Odoo والمنطقة وWorkers والتخزين ودورة الفوترة والإضافات الاختيارية المعروضة."},{"en":"Review the total and complete checkout. Paid provisioning starts after the invoice is settled. Trial behavior depends on availability.","ar":"راجع الإجمالي وأكمل الدفع. يبدأ تجهيز الاشتراك المدفوع بعد تسوية الفاتورة، بينما تتوقف إتاحة التجربة على إعدادات المنصة."},{"en":"Follow the instance status until it is running. Open **Databases** to create a database or restore an existing Odoo backup.","ar":"تابع حالة Instance حتى تعمل، ثم افتح **قواعد البيانات** لإنشاء قاعدة أو استعادة نسخة Odoo موجودة."},{"en":"Open Odoo from the database row and sign in with that database’s administrator credentials.","ar":"افتح Odoo من صف قاعدة البيانات وسجّل ببيانات مسؤول هذه القاعدة."}]}]},{"id":"after","title":{"en":"What happens next","ar":"بعد الإطلاق"},"blocks":[{"type":"paragraph","text":{"en":"Git repositories are connected after purchase in **Code & packages**. Purchased Staging and Development slots reserve capacity; they do not automatically create servers at checkout. An empty hosting site displays the no-database page until a customer database is available.","ar":"يُربط مستودع Git بعد الشراء من **الكود والحزم**. شراء سعة Staging وDevelopment يحجز أماكن للبيئات، لكنه لا ينشئ خوادمها تلقائيًا عند الدفع. يعرض موقع الاستضافة صفحة عدم وجود قاعدة بيانات إلى أن تُنشأ قاعدة للعميل."}}]}],"related":["manage-databases","custom-code","environment-slots","provisioning-troubleshooting"],"sources":["control-plane/saas_website/controllers/main.py","control-plane/saas_core/models/saas_instance.py","frontend/veltnex/src/pages/Hosting.tsx"]},{"id":"free-trial","title":{"en":"Use a free trial","ar":"استخدام الفترة التجريبية"},"summary":{"en":"Understand availability, restrictions, and upgrading a trial.","ar":"تعرّف على إتاحة التجربة وحدودها والانتقال إلى اشتراك مدفوع."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"availability","title":{"en":"Availability and limits","ar":"الإتاحة والحدود"},"blocks":[{"type":"paragraph","text":{"en":"Trials are offered only when enabled and when an eligible trial plan is available. The duration and eligibility are configured by the platform. Use the expiry date shown in your dashboard. Trial accounts cannot buy daily backups, paid compute upgrades, or additional environment slots before upgrading.","ar":"تتاح التجربة عند تفعيلها ووجود خطة تجريبية مؤهلة. تضبط المنصة المدة وشروط الاستحقاق؛ واعتمد على تاريخ الانتهاء المعروض في لوحة التحكم. يلزم الانتقال إلى خطة مدفوعة قبل شراء النسخ اليومية أو ترقيات موارد التشغيل المدفوعة أو سعة بيئات إضافية."}}]},{"id":"upgrade","title":{"en":"Continue with a paid plan","ar":"الانتقال إلى خطة مدفوعة"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open the trial instance and choose **Upgrade plan**.","ar":"افتح Instance التجريبية واختر **ترقية الخطة**."},{"en":"Select an eligible paid plan and billing period, then settle its invoice.","ar":"اختر خطة مدفوعة ودورة فوترة ثم سدّد الفاتورة."},{"en":"Confirm that the paid plan and running state appear before treating the trial as a live service.","ar":"تأكد من ظهور الخطة المدفوعة وحالة التشغيل قبل الاعتماد عليها لخدمة فعلية."}]},{"type":"note","tone":"warning","text":{"en":"After expiry the trial is stopped or suspended according to the lifecycle policy. Do not rely on unlimited retention or backups being included; export any important data before expiry.","ar":"عند انتهاء التجربة يتوقف التشغيل أو يُعلّق وفق سياسة دورة الخدمة. لا تفترض الاحتفاظ بالبيانات إلى أجل غير محدد أو تضمين النسخ الاحتياطية؛ صدّر البيانات المهمة قبل انتهاء التجربة."}}]}],"related":["change-plan","ondemand-backups"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_billing/models/saas_instance.py"]},{"id":"managed-services","title":{"en":"Subscribe to a ready-made service","ar":"الاشتراك في خدمة جاهزة"},"summary":{"en":"Understand the managed-service experience and its available tools.","ar":"تعرّف على تجربة الخدمات الجاهزة والأدوات المتاحة فيها."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"choose","title":{"en":"Choose a service","ar":"اختيار الخدمة"},"blocks":[{"type":"paragraph","text":{"en":"Open **Services**, select an available product, review its description, and configure the offered size and billing options. Products and applications are defined by the platform catalog. Complete checkout and wait for the service to be provisioned.","ar":"افتح **الخدمات** واختر منتجًا متاحًا، واقرأ وصفه ثم حدّد الموارد وخيارات الفوترة المعروضة. تضبط المنصة المنتجات والتطبيقات في الكتالوج. أكمل الدفع وانتظر تجهيز الخدمة."}}]},{"id":"tools","title":{"en":"Management tools","ar":"أدوات الإدارة"},"blocks":[{"type":"paragraph","text":{"en":"A service can expose its overview, power controls, resources, billing, and snapshots. Hosting-only tools such as customer Git repositories, the SQL console, Shell, multi-environment workflows, and the hosting Databases page are not part of the managed-service interface. Use the product description to confirm what is included.","ar":"قد تتيح الخدمة عرض الحالة والتحكم بالتشغيل والموارد والفوترة واللقطات. أدوات الاستضافة مثل مستودعات Git الخاصة بالعميل وSQL وShell والعمل بعدة بيئات وصفحة قواعد بيانات الاستضافة ليست ضمن واجهة الخدمات الجاهزة. راجع وصف المنتج لمعرفة ما يشمله الاشتراك."}}]}],"related":["overview","daily-backups","invoices"],"sources":["frontend/veltnex/src/pages/ServiceDetail.tsx","control-plane/saas_website/controllers/api.py"]}]},{"id":"projects","title":{"en":"Projects and lifecycle","ar":"المشاريع ودورة الخدمة"},"description":{"en":"Navigate owned and shared projects, operate instances, and understand status.","ar":"تنقّل بين مشاريعك والمشاريع المشتركة وتحكّم بالتشغيل وافهم الحالات."},"articles":[{"id":"project-workspace","title":{"en":"Navigate your project workspace","ar":"استخدام مساحة عمل المشروع"},"summary":{"en":"Find your projects and select the environment you can access.","ar":"اعثر على مشاريعك واختر البيئة التي تملك صلاحية الوصول إليها."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"navigation","title":{"en":"Projects and environment selection","ar":"اختيار المشروع والبيئة"},"blocks":[{"type":"paragraph","text":{"en":"The project list and project selector separate **My projects** from **Shared projects**. Owned projects belong to your customer account. Shared projects appear because a teammate role or group grants access. Platform staff can see a broader customer-filtered list according to their platform privileges.","ar":"تفصل قائمة المشاريع ومحدد المشروع بين **مشاريعي** و**المشاريع المشتركة**. ترتبط مشاريعك بحساب العميل الخاص بك، وتظهر المشاريع المشتركة بسبب دور مُنح لك مباشرة أو عبر مجموعة. قد يرى موظفو المنصة قائمة أوسع مع إمكانية التصفية حسب العميل وفق صلاحياتهم."}},{"type":"list","ordered":true,"items":[{"en":"Open **Projects**, select a hosting project, and choose a Production, Staging, or Development environment.","ar":"افتح **المشاريع**، واختر مشروع استضافة ثم بيئة Production أو Staging أو Development."},{"en":"Use the environment tabs for Overview, Metrics, Databases, Shell, SQL, Logs, or Snapshots. Tabs depend on your permissions and the product type.","ar":"استخدم تبويبات البيئة للملخص والمقاييس وقواعد البيانات وShell وSQL والسجلات واللقطات. تتحدد التبويبات حسب صلاحياتك ونوع المنتج."},{"en":"Use the top project selector to switch projects. The Projects navigation action is also available from Settings and Team & permissions.","ar":"بدّل المشروع من المحدد العلوي. ويمكنك الوصول مباشرة إلى المشاريع من التنقل في الإعدادات وصفحة الفريق والصلاحيات."}]}]},{"id":"scopes","title":{"en":"Why a shared project can look empty","ar":"لماذا قد يبدو المشروع المشترك فارغًا؟"},"blocks":[{"type":"paragraph","text":{"en":"A Staging-only grant makes the project discoverable but does not authorize Production. If no Staging environment exists, the workspace explains that no environments are available in your assigned scopes. Ask the owner to create an environment or change your scope only if you need that access.","ar":"يُظهر منح الوصول إلى Staging المشروع في قائمتك، لكنه لا يسمح بدخول Production. إذا لم توجد بيئة Staging، توضح مساحة العمل أنه لا توجد بيئات ضمن النطاقات الممنوحة لك. اطلب من المالك إنشاء البيئة أو تعديل النطاق إذا كنت بحاجة إلى هذا الوصول."}}]}],"related":["iam-overview","iam-scopes","environment-create"],"sources":["frontend/veltnex/src/pages/portal/Instances.tsx","frontend/veltnex/src/components/ProjectSwitcher.tsx","frontend/veltnex/src/pages/portal/Environments.tsx"]},{"id":"access-power","title":{"en":"Start, stop, and restart an instance","ar":"بدء تشغيل Instance وإيقافها وإعادة تشغيلها"},"summary":{"en":"Operate an instance without confusing stopping with cancellation.","ar":"تحكّم بالتشغيل وافهم الفرق بين الإيقاف وإلغاء الاشتراك."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before you begin","ar":"قبل البدء"},"blocks":[{"type":"paragraph","text":{"en":"Use an owner account or the **Instance Operator** role in the selected environment. Wait for an active operation to finish before issuing another command. Application login credentials are managed separately from your VELTNEX login.","ar":"استخدم حساب المالك أو دور **مسؤول تشغيل Instance** في البيئة المختارة. انتظر اكتمال العملية الجارية قبل إرسال أمر آخر. بيانات الدخول إلى التطبيق مستقلة عن بيانات دخول VELTNEX."}}]},{"id":"controls","title":{"en":"Power controls","ar":"أوامر التشغيل"},"blocks":[{"type":"table","headers":[{"en":"Action","ar":"الإجراء"},{"en":"Result","ar":"النتيجة"}],"rows":[[{"en":"Start","ar":"Start"},{"en":"Starts a stopped instance.","ar":"يشغّل Instance متوقفة."}],[{"en":"Stop","ar":"Stop"},{"en":"Stops the application; it does not cancel the subscription or release paid capacity.","ar":"يوقف التطبيق دون إلغاء الاشتراك أو تحرير السعة المدفوعة."}],[{"en":"Restart","ar":"Restart"},{"en":"Restarts the application and can interrupt active requests.","ar":"يعيد تشغيل التطبيق وقد يقطع الطلبات الجارية."}]]},{"type":"paragraph","text":{"en":"Open the environment overview and select the available power action. Follow the status until it settles. If the instance is suspended for billing or storage capacity, resolve that cause; Start is not a substitute for clearing the restriction.","ar":"افتح ملخص البيئة واختر أمر التشغيل المتاح، ثم تابع الحالة حتى تستقر. إذا كانت Instance معلّقة بسبب الفوترة أو امتلاء التخزين، عالج السبب؛ أمر بدء التشغيل لا يتجاوز هذه القيود."}}]}],"related":["instance-status","storage-capacity"],"sources":["control-plane/saas_website/controllers/api.py","control-plane/saas_core/models/saas_instance.py"]},{"id":"instance-status","title":{"en":"Instance status reference","ar":"مرجع حالات Instance"},"summary":{"en":"Interpret payment, provisioning, running, and failure states.","ar":"افهم حالات الدفع والتجهيز والتشغيل والإخفاق."},"kind":"reference","reviewed":"2026-10-05","sections":[{"id":"states","title":{"en":"Status meanings","ar":"معاني الحالات"},"blocks":[{"type":"table","headers":[{"en":"State","ar":"الحالة"},{"en":"Meaning and next action","ar":"المعنى والإجراء التالي"}],"rows":[[{"en":"Pending payment","ar":"Pending payment"},{"en":"Checkout is incomplete. Settle the invoice to activate the order.","ar":"لم يكتمل الدفع. سدّد الفاتورة لتفعيل الطلب."}],[{"en":"Paid / Pending provision","ar":"Paid / Pending provision"},{"en":"Payment is recorded; allocation or infrastructure readiness is pending.","ar":"سُجّل الدفع، ويجري انتظار تخصيص الموارد أو جاهزية البنية."}],[{"en":"Provisioning","ar":"Provisioning"},{"en":"A background lifecycle operation is running. Read the operation details before retrying.","ar":"تجري عملية في الخلفية ضمن دورة الخدمة. راجع تفاصيلها قبل إعادة المحاولة."}],[{"en":"Running","ar":"Running"},{"en":"The application is running. A hosting customer database may still need to be created.","ar":"التطبيق يعمل، وقد تحتاج الاستضافة إلى إنشاء قاعدة بيانات للعميل."}],[{"en":"Stopped","ar":"Stopped"},{"en":"The application is stopped; capacity and subscription still exist.","ar":"التطبيق متوقف مع بقاء السعة والاشتراك."}],[{"en":"Suspended","ar":"Suspended"},{"en":"A restriction such as unpaid renewal or capacity has paused operation.","ar":"أوقف قيد مثل تجديد غير مدفوع أو امتلاء السعة التشغيل مؤقتًا."}],[{"en":"Failed","ar":"Failed"},{"en":"An operation failed. Inspect the error and deployment history.","ar":"أخفقت عملية. راجع رسالة الخطأ وسجل Deployment."}],[{"en":"Cancelled","ar":"Cancelled"},{"en":"Infrastructure has been removed or cancellation has completed.","ar":"أزيلت البنية أو اكتمل إلغاء الخدمة."}]]}]},{"id":"timing","title":{"en":"Asynchronous operations","ar":"عمليات الخلفية"},"blocks":[{"type":"paragraph","text":{"en":"Creation, deployments, restore, and deletion can continue after their request returns. A browser refresh is not a completion signal. The platform serializes conflicting work and has retry and stuck-operation recovery, but network, capacity, Git, or storage failures can still require support.","ar":"قد يستمر الإنشاء وDeployment والاستعادة والحذف بعد قبول الطلب. تحديث المتصفح لا يعني اكتمال العملية. تنظّم المنصة العمليات المتعارضة وتوفّر إعادة المحاولة ومعالجة العمليات المتعثرة، لكن أعطال الشبكة أو السعة أو Git أو التخزين قد تستلزم تدخل الدعم."}}]}],"related":["provisioning-troubleshooting","deployment-troubleshooting"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_core/models/saas_job.py"]},{"id":"reactivate","title":{"en":"Cancel and reactivate a project","ar":"إلغاء المشروع وإعادة تفعيله"},"summary":{"en":"Understand cascading deletion, retained data, and recovery conditions.","ar":"افهم حذف البيئات التابعة وشروط الاحتفاظ بالبيانات والاستعادة."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"cancel","title":{"en":"Before cancelling","ar":"قبل الإلغاء"},"blocks":[{"type":"paragraph","text":{"en":"Production subscription cancellation and reactivation are customer-owner billing actions. The current portal does not expose a general active-subscription cancellation button. Contact support as the owner to arrange cancellation; declining an optional unpaid invoice is a separate workflow and is not active subscription cancellation.","ar":"إلغاء اشتراك Production وإعادة تفعيله من إجراءات فوترة مالك العميل. لا تعرض اللوحة الحالية زرًا عامًا لإلغاء اشتراك فعّال. تواصل مع الدعم بصفتك المالك لترتيب الإلغاء؛ فرفض فاتورة اختيارية غير مدفوعة إجراء مستقل وليس إلغاءً لاشتراك فعّال."}},{"type":"note","tone":"warning","text":{"en":"Cancelling a Production project also tears down its Staging and Development servers. Export important databases first. Cancellation is different from Stop.","ar":"إلغاء مشروع Production يزيل أيضًا خوادم Staging وDevelopment التابعة له. صدّر قواعد البيانات المهمة أولًا. الإلغاء يختلف عن إيقاف التشغيل."}},{"type":"paragraph","text":{"en":"During teardown the platform attempts a fresh full-instance snapshot and removes older snapshots and on-demand backups. Only a successfully captured fresh snapshot is retained; if capture fails, there may be no retained recovery copy. Never assume the most recent old backup will survive cancellation.","ar":"أثناء الإزالة تحاول المنصة أخذ لقطة جديدة كاملة، وتحذف اللقطات الأقدم والنسخ الاحتياطية اليدوية. لا يُحتفظ إلا باللقطة الجديدة إذا نجح التقاطها؛ وإذا أخفقت العملية فقد لا تتوفر نسخة للاستعادة. لا تفترض بقاء أحدث نسخة قديمة بعد الإلغاء."}}]},{"id":"reactivate","title":{"en":"Reactivate and restore","ar":"إعادة التفعيل والاستعادة"},"blocks":[{"type":"paragraph","text":{"en":"If Reactivate is offered, select a paid plan and complete its checkout. Reactivation creates fresh infrastructure; restoring retained data is a separate recovery step and may require daily backups to be enabled and a restoration invoice to be settled. Review the price and snapshot availability shown before confirming. Retained snapshots are not a promise of indefinite storage.","ar":"إذا ظهر خيار إعادة التفعيل، اختر خطة مدفوعة وأكمل الدفع. تُنشئ إعادة التفعيل بنية جديدة؛ أما استعادة البيانات المحتفظ بها فهي خطوة مستقلة قد تتطلب تفعيل النسخ اليومية وتسوية فاتورة الاستعادة. راجع التكلفة وإتاحة اللقطة قبل التأكيد. الاحتفاظ بلقطة لا يعني ضمان تخزينها إلى أجل غير محدد."}}]}],"related":["restore","invoices","ondemand-backups"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_billing/models/saas_instance.py","control-plane/saas_billing/models/account_move.py","control-plane/saas_iam/models/integration.py","frontend/veltnex/src/pages/portal/InstanceDetail.tsx"]},{"id":"access-urls","title":{"en":"Instance addresses, HTTPS, and website access","ar":"عناوين Instance وHTTPS والوصول للموقع"},"summary":{"en":"Understand subdomains, secure transport, public pages, and application login.","ar":"افهم النطاقات الفرعية والاتصال الآمن والصفحات العامة ودخول التطبيق."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"address","title":{"en":"Your instance address","ar":"عنوان Instance"},"blocks":[{"type":"paragraph","text":{"en":"Choose an available subdomain and a platform-provided Domain during configuration. The resulting address identifies the instance. Environment names can receive a project-derived unique subdomain. Names and database prefixes are technical identifiers; avoid renaming assumptions after creation.","ar":"اختر نطاقًا فرعيًا متاحًا وDomain توفره المنصة أثناء الإعداد. يحدد العنوان الناتج Instance، وقد تحصل البيئات على نطاق فرعي فريد مشتق من المشروع. الأسماء وبادئات القواعد معرّفات تقنية؛ فلا تفترض إمكان تغييرها بعد الإنشاء."}}]},{"id":"https","title":{"en":"HTTPS and public access","ar":"HTTPS والوصول العام"},"blocks":[{"type":"paragraph","text":{"en":"Provisioning configures HTTPS through the platform infrastructure. A certificate or routing failure requires infrastructure diagnosis, not a database password reset. With an available customer database, visitors reach the Odoo website/application; with no customer database they see the no-database page. Whether an Odoo page is public is controlled by your application configuration.","ar":"يُعدّ التجهيز HTTPS عبر بنية المنصة. يحتاج إخفاق الشهادة أو التوجيه إلى تشخيص البنية وليس إعادة كلمة مرور القاعدة. عند وجود قاعدة العميل يصل الزوار إلى موقع أو تطبيق Odoo، وعند غيابها يرون صفحة عدم وجود قاعدة. تحدد إعدادات تطبيقك ما إذا كانت صفحة Odoo عامة."}}]},{"id":"custom","title":{"en":"Custom addresses and access","ar":"العناوين المخصصة والوصول"},"blocks":[{"type":"paragraph","text":{"en":"Use Open on the instance or database page for the correct address. VELTNEX IAM controls infrastructure tools, while Odoo controls application users and public website content. A custom Domain or region move is not exposed as a general self-service editor in the current portal; contact support to check availability and migration requirements.","ar":"استخدم الفتح من صفحة Instance أو القاعدة للوصول إلى العنوان الصحيح. تضبط IAM في VELTNEX أدوات البنية، بينما يضبط Odoo مستخدمي التطبيق والمحتوى العام. لا تتيح اللوحة الحالية محررًا عامًا ذاتيًا لـ Domain مخصص أو نقل المنطقة؛ تواصل مع الدعم للتحقق من الإتاحة ومتطلبات النقل."}}]}],"related":["launch-instance","database-access","account-settings"],"sources":["control-plane/saas_core/models/saas_instance.py","compute/operator/internal/resources/route.go"]},{"id":"dashboard-navigation","title":{"en":"Dashboard search and notifications","ar":"بحث لوحة التحكم والإشعارات"},"summary":{"en":"Navigate quickly and understand which alerts the dashboard displays.","ar":"تنقّل بسرعة وافهم التنبيهات التي تعرضها لوحة التحكم."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"search","title":{"en":"Search and navigation","ar":"البحث والتنقل"},"blocks":[{"type":"paragraph","text":{"en":"Use the top search control or Ctrl/⌘ + K to open the command palette. Search available projects, pages, and actions; use arrow keys and Enter to select and Escape to close. The project selector separates owned and shared projects. Choosing a search result never adds permissions to a restricted environment.","ar":"افتح قائمة البحث من الشريط العلوي أو Ctrl/⌘ + K. ابحث عن المشاريع والصفحات والإجراءات المتاحة، واستخدم الأسهم وEnter للاختيار وEscape للإغلاق. يفصل محدد المشروع بين مشاريعك والمشاريع المشتركة. اختيار نتيجة لا يضيف صلاحيات لبيئة مقيّدة."}}]},{"id":"notifications","title":{"en":"Notifications and action items","ar":"الإشعارات والإجراءات المطلوبة"},"blocks":[{"type":"paragraph","text":{"en":"The dashboard highlights outstanding checkout and invoices, failed or suspended instances, and other available account signals. The header bell summarizes account signals and links to their pages; it is not a permanent notification archive or a configurable alert-rule system. Review the underlying invoice or instance status before acting. Teammates see only the data their permissions allow.","ar":"تبرز لوحة التحكم الدفع غير المكتمل والفواتير والـ Instances المخفقة أو المعلّقة والإشارات المتاحة للحساب. يلخص جرس الشريط العلوي هذه الإشارات ويربط بصفحاتها؛ وليس أرشيفًا دائمًا للإشعارات أو نظام قواعد تنبيه قابلًا للضبط. راجع الفاتورة أو الحالة الأصلية قبل التصرف. لا يرى أعضاء الفريق إلا البيانات التي تسمح بها صلاحياتهم."}}]}],"related":["project-workspace","invoices","instance-status"],"sources":["frontend/veltnex/src/components/CommandPalette.tsx","frontend/veltnex/src/components/NotificationsBell.tsx","frontend/veltnex/src/pages/portal/Dashboard.tsx"]}]},{"id":"plans","title":{"en":"Plans and capacity","ar":"الخطط والسعة"},"description":{"en":"Choose compatible resources, scale safely, and manage capacity add-ons.","ar":"اختر موارد متوافقة ووسّعها بأمان وأدر إضافات السعة."},"articles":[{"id":"sizing","title":{"en":"Choose Workers and storage","ar":"اختيار Workers والتخزين"},"summary":{"en":"Size the application based on workload, data, and measured usage.","ar":"حدّد الموارد حسب عبء العمل وحجم البيانات والاستخدام الفعلي."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"resources","title":{"en":"What you are sizing","ar":"الموارد التي تختارها"},"blocks":[{"type":"paragraph","text":{"en":"Workers are Odoo request-handling processes, not a fixed number of licensed users. Concurrency also depends on CPU, RAM, query cost, custom modules, and background tasks. Storage covers the instance’s database and application files, including attachments. Snapshot objects are stored separately.","ar":"Workers هي عمليات معالجة طلبات Odoo وليست عددًا ثابتًا من المستخدمين المرخّصين. وتتأثر القدرة على العمل المتزامن أيضًا بـ CPU وRAM وكلفة الاستعلامات والوحدات المخصصة والمهام الخلفية. يشمل التخزين قاعدة البيانات وملفات التطبيق والمرفقات، بينما تُخزّن ملفات اللقطات بشكل مستقل."}}]},{"id":"choose","title":{"en":"Choose and validate a size","ar":"اختيار السعة والتحقق منها"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Choose a published plan or supported custom size from Hosting.","ar":"اختر خطة منشورة أو موارد مخصصة مدعومة من صفحة الاستضافة."},{"en":"Compare measured CPU, RAM, and storage during representative peak usage, not only while idle.","ar":"قارن CPU وRAM والتخزين أثناء ذروة استخدام تمثل عملك الفعلي، وليس أثناء الخمول فقط."},{"en":"Increase resources when sustained pressure affects users. Investigate expensive queries and custom code as well as capacity.","ar":"زد الموارد عندما يؤثر الضغط المستمر على المستخدمين، وراجع أيضًا الاستعلامات المكلفة والكود المخصص."}]}]}],"related":["monitoring","change-plan","storage-capacity"],"sources":["control-plane/saas_core/models/saas_plan.py","control-plane/saas_core/models/saas_instance.py"]},{"id":"region-version","title":{"en":"Choose a region, Odoo version, and edition","ar":"اختيار المنطقة وإصدار Odoo ونسخته"},"summary":{"en":"Match application compatibility and infrastructure availability.","ar":"وازن بين توافق التطبيق وإتاحة البنية."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"region","title":{"en":"Region","ar":"المنطقة"},"blocks":[{"type":"paragraph","text":{"en":"Choose among active regions offered in the configurator. A nearby location can reduce network latency, but the actual placement also depends on healthy available capacity. Region is not a self-service move setting after creation; moving requires a planned new deployment and data transfer.","ar":"اختر من المناطق النشطة في صفحة الإعداد. قد يخفّض الموقع الأقرب زمن الاتصال، لكن تخصيص الموارد يعتمد أيضًا على السعة المتاحة وحالة البنية. لا يوجد إعداد لنقل المنطقة مباشرة بعد الإنشاء؛ ويتطلب النقل تجهيزًا جديدًا مخططًا ونقل البيانات."}}]},{"id":"version","title":{"en":"Version and edition","ar":"الإصدار والنسخة"},"blocks":[{"type":"paragraph","text":{"en":"The website lists Odoo 13 through Odoo 20. An advertised version is selectable only when its catalog record and compatible runtime image are enabled. Community and Enterprise are distinct editions. Match your modules and backup to the selected major version; changing a plan does not migrate a database to another Odoo major version.","ar":"يعرض الموقع إصدارات Odoo من 13 إلى Odoo 20. لا يمكن اختيار الإصدار المعروض إلا إذا كان سجلّه وصورة التشغيل المتوافقة معه مفعّلين. Community وEnterprise نسختان مختلفتان. تأكد من توافق وحداتك ونسختك الاحتياطية مع الإصدار الرئيسي المختار؛ فتغيير الخطة لا ينقل قاعدة البيانات إلى إصدار رئيسي آخر من Odoo."}}]}],"related":["custom-code","database-restore","launch-instance"],"sources":["frontend/veltnex/src/pages/Home.tsx","control-plane/saas_core/models/saas_odoo_version.py","control-plane/saas_core/data/saas_odoo_version_data.xml"]},{"id":"change-plan","title":{"en":"Change a subscription plan","ar":"تغيير خطة الاشتراك"},"summary":{"en":"Understand payment-gated upgrades and scheduled downgrades.","ar":"افهم الترقيات المرتبطة بالدفع والانتقال المجدول إلى خطة أقل."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before you begin","ar":"قبل البدء"},"blocks":[{"type":"paragraph","text":{"en":"Plan and purchased-capacity changes are owner billing actions. A Project Administrator teammate does not gain these permissions. Review the current plan, usage, billing period, and any pending invoice or scheduled change.","ar":"تغيير الخطة والسعة المشتراة من صلاحيات فوترة المالك. لا يمنح دور مدير المشروع لعضو الفريق هذه الصلاحيات. راجع الخطة الحالية والاستخدام ودورة الفوترة وأي فاتورة أو تغيير مجدول."}}]},{"id":"behavior","title":{"en":"How changes apply","ar":"كيف تُطبّق التغييرات؟"},"blocks":[{"type":"table","headers":[{"en":"Change","ar":"التغيير"},{"en":"Behavior","ar":"السلوك"}],"rows":[[{"en":"Upgrade","ar":"الترقية"},{"en":"An invoice is created; the paid change applies after settlement. Unused prepaid value is accounted for in the quote and wallet/credit flow.","ar":"تُنشأ فاتورة ويُطبّق التغيير المدفوع بعد تسويتها، مع احتساب القيمة المدفوعة للوقت غير المستخدم ضمن التسعير والرصيد."}],[{"en":"Downgrade","ar":"خطة أقل"},{"en":"Scheduled for the cycle boundary. Storage usage must be below 75% of the target plan limit, leaving at least 25% free; insufficient or unavailable usage measurements can block the request.","ar":"تُجدول عند نهاية الدورة. يجب أن يقل استخدام التخزين عن 75% من حد الخطة المستهدفة ليترك 25% على الأقل شاغرًا؛ وقد يُرفض الطلب إذا كان الاستخدام مرتفعًا أو تعذّر قياسه."}],[{"en":"Cancel scheduled change","ar":"إلغاء التغيير المجدول"},{"en":"Removes the pending downgrade before it takes effect.","ar":"يلغي الانتقال إلى الخطة الأقل قبل تطبيقه."}]]}]},{"id":"steps","title":{"en":"Request a change","ar":"طلب التغيير"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open the instance and choose **Change plan** or **Upgrade plan** for a trial.","ar":"افتح Instance واختر **تغيير الخطة** أو **ترقية الخطة** للتجربة."},{"en":"Select the plan and monthly or yearly billing, then review the quote.","ar":"اختر الخطة والفوترة الشهرية أو السنوية وراجع التسعير."},{"en":"Complete checkout if payment is required, or confirm the scheduled downgrade.","ar":"أكمل الدفع إذا لزم أو أكّد التغيير المجدول إلى الخطة الأقل."},{"en":"Check the active or scheduled plan in the overview. Resource changes can take time to reconcile.","ar":"تحقق من الخطة الفعلية أو المجدولة في الملخص. قد يحتاج تطبيق الموارد إلى بعض الوقت."}]}]}],"related":["billing-options","optional-charges","storage-capacity"],"sources":["control-plane/saas_billing/models/saas_instance.py","frontend/veltnex/src/pages/portal/InstanceDetail.tsx"]},{"id":"storage-capacity","title":{"en":"Manage storage capacity and blocks","ar":"إدارة سعة التخزين والإضافات"},"summary":{"en":"Respond to capacity warnings and safely release unused storage.","ar":"تعامل مع تنبيهات السعة وحرّر التخزين غير المستخدم بأمان."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"thresholds","title":{"en":"Capacity states","ar":"حالات السعة"},"blocks":[{"type":"paragraph","text":{"en":"The capacity checker warns at 80% usage and starts a grace period at 100%. The default storage grace period is 7 days and can be changed by the platform. Continued over-capacity usage after that period can pause the workspace. These checks use measured usage and periodic jobs, so displayed values are not an instantaneous hard quota.","ar":"يصدر تنبيه السعة عند استخدام 80% ويبدأ مهلة عند بلوغ 100%. المهلة الافتراضية للتخزين 7 أيام، ويمكن للمنصة تعديلها. استمرار تجاوز السعة بعد المهلة قد يوقف مساحة العمل مؤقتًا. تعتمد الفحوص على قياسات ومهام دورية، لذلك لا تمثل القيم المعروضة حدًا فوريًا صارمًا."}}]},{"id":"actions","title":{"en":"Expand or release capacity","ar":"زيادة السعة أو تحريرها"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Review the capacity message and current usage on the instance overview.","ar":"راجع رسالة السعة والاستخدام الحالي في ملخص Instance."},{"en":"Upgrade the plan or buy the storage blocks offered by the interface. Block size and price are configured by the platform; paid additions activate after payment.","ar":"رقِّ الخطة أو اشترِ إضافات التخزين المعروضة. تضبط المنصة حجم الإضافة وسعرها، وتُفعّل الإضافات المدفوعة بعد الدفع."},{"en":"To release blocks, first remove enough data to satisfy the headroom check. Confirm the resulting capacity and recurring charge; no automatic refund is promised for released storage.","ar":"قبل تحرير الإضافات، خفّض البيانات بما يكفي لاجتياز فحص هامش السعة. راجع السعة الناتجة والتكلفة المتكررة؛ ولا تفترض استردادًا تلقائيًا لقيمة التخزين المحرّر."}]}]}],"related":["sizing","change-plan"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_billing/models/saas_instance.py"]}]},{"id":"environments","title":{"en":"Staging and Development","ar":"بيئات Staging وDevelopment"},"description":{"en":"Create isolated environments, copy data, merge code, and manage reserved slots.","ar":"أنشئ بيئات مستقلة وانسخ البيانات وادمج الكود وأدر السعة المحجوزة."},"articles":[{"id":"environment-slots","title":{"en":"Reserve and release environment slots","ar":"حجز سعة البيئات وتحريرها"},"summary":{"en":"Distinguish paid capacity from the servers running inside it.","ar":"ميّز بين السعة المدفوعة والخوادم التي تعمل ضمنها."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"model","title":{"en":"Slots and servers","ar":"السعة والخوادم"},"blocks":[{"type":"paragraph","text":{"en":"A slot is prepaid capacity for one Staging or Development server. Staging and Development have separate slot counts. Purchasing slots does not create environments automatically. Creating, deleting, and recreating servers within the purchased count reuses the slot without a second slot purchase. Unused reserved slots remain billable until released.","ar":"المكان المحجوز سعة مدفوعة مسبقًا لخادم Staging أو Development واحد. لكل نوع عدد مستقل من الأماكن. شراء السعة لا ينشئ البيئات تلقائيًا، ويمكن إنشاء الخوادم وحذفها وإعادة إنشائها ضمن العدد المشترى دون شراء المكان مرة أخرى. تظل الأماكن المحجوزة غير المستخدمة خاضعة للفوترة إلى أن تحرّرها."}}]},{"id":"manage","title":{"en":"Manage capacity","ar":"إدارة السعة"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"As the owner, open the project’s resources or environment capacity controls. Review used and total slots for each type.","ar":"بصفتك المالك، افتح أدوات موارد المشروع أو سعة البيئات، وراجع العدد المستخدم والإجمالي لكل نوع."},{"en":"Reserve the required quantity and complete payment if checkout is required. Slots are granted after settlement and recur with the project subscription.","ar":"احجز العدد المطلوب وأكمل الدفع إذا لزم. تُمنح السعة بعد التسوية وتُجدّد مع اشتراك المشروع."},{"en":"To stop paying for unused capacity, release unused slots. You cannot release occupied slots; delete their environments first.","ar":"لإيقاف تكلفة السعة غير المستخدمة، حرّر الأماكن الشاغرة. لا يمكن تحرير مكان مشغول؛ احذف بيئته أولًا."},{"en":"Review the wallet credit for unused time and the reduced recurring count after release.","ar":"راجع رصيد الوقت غير المستخدم في المحفظة والعدد الأقل الذي ستشمله الفوترة المتكررة."}]}]},{"id":"permissions","title":{"en":"Who can manage slots","ar":"من يملك إدارة السعة؟"},"blocks":[{"type":"paragraph","text":{"en":"Only the owner or a platform administrator manages purchased capacity. **Environment Creator** allows a teammate to create environments within already reserved slots; it does not authorize purchases. Trials must upgrade before adding slots. A Git repository is required to create a server, but not to reserve capacity.","ar":"إدارة السعة المشتراة من صلاحيات المالك أو مسؤول المنصة. يسمح دور **مسؤول إنشاء البيئات** لعضو الفريق بإنشاء بيئات ضمن السعة المحجوزة، ولا يسمح له بالشراء. يلزم ترقية التجربة قبل إضافة السعة. إنشاء الخادم يحتاج مستودع Git، أما حجز السعة فلا يحتاجه."}}]}],"related":["environment-create","environment-delete","wallet"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_billing/models/saas_instance.py"]},{"id":"environment-create","title":{"en":"Create a Staging or Development environment","ar":"إنشاء بيئة Staging أو Development"},"summary":{"en":"Use a reserved slot and an existing or new Git branch.","ar":"استخدم مكانًا محجوزًا وفرع Git موجودًا أو جديدًا."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before you begin","ar":"قبل البدء"},"blocks":[{"type":"list","ordered":false,"items":[{"en":"Use a paid hosting project with a repository connected to Production.","ar":"استخدم مشروع استضافة مدفوعًا بمستودع مرتبط بـ Production."},{"en":"Have an unused reserved slot of the required type and **Environment Creator** access for that type.","ar":"تأكد من وجود مكان شاغر للنوع المطلوب وصلاحية **مسؤول إنشاء البيئات** لهذا النوع."},{"en":"Ensure the repository token can read code and perform any required branch operation.","ar":"تأكد من قدرة Token المستودع على قراءة الكود وتنفيذ عمليات الفروع اللازمة."}]}]},{"id":"steps","title":{"en":"Create the environment","ar":"خطوات الإنشاء"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open the project workspace and choose to create Staging or Development.","ar":"افتح مساحة المشروع واختر إنشاء Staging أو Development."},{"en":"Enter the environment name. Development requires a name. Select an existing branch or specify a new branch; when omitted the branch uses the environment name.","ar":"أدخل اسم البيئة، وهو مطلوب في Development. اختر فرعًا موجودًا أو حدّد فرعًا جديدًا؛ وإذا لم تحدّد فرعًا يُستخدم اسم البيئة."},{"en":"Confirm creation and follow provisioning and the initial code build. The environment inherits the project repository and Odoo version.","ar":"أكّد الإنشاء وتابع التجهيز وبناء الكود الأول. ترث البيئة مستودع المشروع وإصدار Odoo."},{"en":"Open Databases to create or restore data, or use the project’s database-copy workflow.","ar":"افتح قواعد البيانات لإنشائها أو استعادتها، أو استخدم نسخ قواعد البيانات داخل المشروع."}]}]},{"id":"data","title":{"en":"Data and isolation","ar":"البيانات والاستقلال"},"blocks":[{"type":"note","tone":"warning","text":{"en":"Do not assume creation automatically clones Production data, loads demo data, or disables outgoing email, scheduled actions, payments, and integrations. Confirm the new environment’s actual databases and configure test-safe application settings before use.","ar":"لا تفترض أن الإنشاء ينسخ بيانات Production تلقائيًا أو يضيف بيانات تجريبية أو يعطّل البريد الصادر والمهام المجدولة والمدفوعات والتكاملات. تحقّق من قواعد البيانات الفعلية واضبط التطبيق بما يناسب الاختبار قبل استخدامه."}},{"type":"paragraph","text":{"en":"Staging and Development are separate runtime and data environments. Their Databases tools are not subject to the single-customer-database Production limit, although storage capacity still applies.","ar":"Staging وDevelopment بيئتان مستقلتان في التشغيل والبيانات. لا تخضع أدوات قواعد البيانات فيهما لحد قاعدة العميل الواحدة في Production، مع بقاء قيود سعة التخزين."}}]}],"related":["environment-copy","environment-slots","provisioning-troubleshooting"],"sources":["control-plane/saas_core/models/saas_instance.py","frontend/veltnex/src/pages/portal/Environments.tsx"]},{"id":"environment-copy","title":{"en":"Copy databases between environments","ar":"نسخ قواعد البيانات بين البيئات"},"summary":{"en":"Copy selected databases into Staging or Development in the same project.","ar":"انسخ قواعد مختارة إلى Staging أو Development داخل المشروع نفسه."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Requirements","ar":"المتطلبات"},"blocks":[{"type":"paragraph","text":{"en":"Source and target must be different running hosting instances in the same project. The target must be Staging or Development. You need **Database Backup Downloader** on the source and **Database Restore Operator** on the target. The database-copy action cannot target Production.","ar":"يجب أن يكون المصدر والهدف بيئتي استضافة مختلفتين وتعملان داخل المشروع نفسه، وأن يكون الهدف Staging أو Development. تحتاج دور **مسؤول تنزيل النسخ الاحتياطية** في المصدر و**مسؤول استعادة قواعد البيانات** في الهدف. لا يمكن أن تكون Production هدفًا لأداة النسخ هذه."}}]},{"id":"steps","title":{"en":"Select and copy","ar":"الاختيار والنسخ"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open the copy-data action, choose the source and target, then select the source databases.","ar":"افتح إجراء نسخ البيانات، وحدّد المصدر والهدف ثم قواعد المصدر المطلوبة."},{"en":"Review the target names. The source prefix is replaced by the target environment prefix.","ar":"راجع أسماء الهدف؛ إذ تُستبدل بادئة المصدر ببادئة البيئة المستهدفة."},{"en":"Explicitly confirm overwrite for each target database that already exists. Unconfirmed conflicts are skipped.","ar":"أكّد الاستبدال صراحة لكل قاعدة موجودة في الهدف. تُتجاوز التعارضات غير المؤكدة."},{"en":"Start the copy and check progress, target databases, and errors. A batch can partially succeed.","ar":"ابدأ النسخ وراجع التقدم وقواعد الهدف والأخطاء. قد تنجح بعض قواعد الدفعة وتخفق أخرى."}]}]},{"id":"safety","title":{"en":"What is copied","ar":"ما الذي يُنسخ؟"},"blocks":[{"type":"paragraph","text":{"en":"The operation copies the selected database dump and its filestore. Other target databases are left alone. Copying data does not merge code, migrate a major Odoo version, or prove that test integrations are disabled. Check outgoing mail, jobs, payment providers, and external connections before testing with copied live data.","ar":"تنسخ العملية بيانات القاعدة ومجلد مرفقاتها، وتترك قواعد الهدف الأخرى دون تغيير. نسخ البيانات لا يدمج الكود ولا يهاجر بين إصدارات Odoo الرئيسية، ولا يثبت تعطيل تكاملات الاختبار. راجع البريد الصادر والمهام ومزوّدي الدفع والاتصالات الخارجية قبل اختبار نسخة من البيانات الفعلية."}}]}],"related":["environment-create","database-restore","environment-merge"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_iam/models/integration.py"]},{"id":"environment-merge","title":{"en":"Merge code between environments","ar":"دمج الكود بين البيئات"},"summary":{"en":"Promote a source Git branch into a target branch without copying data.","ar":"انقل تغييرات فرع Git إلى الفرع المستهدف دون نسخ البيانات."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before merging","ar":"قبل الدمج"},"blocks":[{"type":"paragraph","text":{"en":"Choose two environments in the same project and connected repository. You need project-view access to the source and **Deployment Operator** access to the target. Check both branch names and test the source code before merging into Production. The repository credential must permit the provider’s merge operation.","ar":"اختر بيئتين داخل المشروع نفسه ولهما مستودع مرتبط. تحتاج وصول عرض المشروع في المصدر ودور **مسؤول Deployment** في الهدف. راجع اسمي الفرعين واختبر كود المصدر قبل الدمج إلى Production. يجب أن يسمح اعتماد المستودع بعملية الدمج لدى المزوّد."}}]},{"id":"steps","title":{"en":"Merge and verify","ar":"الدمج والتحقق"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Use the workspace merge action or drag the source environment to the target where the interface offers it.","ar":"استخدم إجراء الدمج في مساحة العمل، أو اسحب بيئة المصدر إلى الهدف عندما تتيح الواجهة ذلك."},{"en":"Review the direction: source changes go into the target branch. Confirm the merge.","ar":"راجع الاتجاه: تنتقل تغييرات المصدر إلى فرع الهدف، ثم أكّد الدمج."},{"en":"If the provider reports a successful merge and the target is running or stopped, the platform requests a target redeployment. Follow its Deployment history.","ar":"إذا نجح الدمج لدى المزوّد وكان الهدف يعمل أو متوقفًا، تطلب المنصة إعادة Deployment للهدف. تابع السجل."},{"en":"Resolve Git conflicts or protected-branch restrictions in your Git provider, then retry when appropriate.","ar":"عالج تعارضات Git أو قيود الفرع المحمي لدى مزوّد Git، ثم أعد المحاولة عند الحاجة."}]}]},{"id":"difference","title":{"en":"Code is separate from data","ar":"الكود مستقل عن البيانات"},"blocks":[{"type":"note","tone":"warning","text":{"en":"Merging does not copy or replace databases. A Deployment rollback also does not reverse database migrations. Back up live data before changes that alter schema or loaded Odoo data.","ar":"الدمج لا ينسخ قواعد البيانات ولا يستبدلها. كذلك لا يعكس التراجع عن Deployment تغييرات قاعدة البيانات. احتفظ بنسخة من البيانات الفعلية قبل تعديل بنية القاعدة أو البيانات التي يحمّلها Odoo."}}]}],"related":["custom-code","module-upgrades","deployment-history"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_core/models/saas_instance_repo.py"]},{"id":"environment-delete","title":{"en":"Delete an environment or its Git branch","ar":"حذف بيئة أو فرع Git الخاص بها"},"summary":{"en":"Remove a non-production server and choose whether to keep its branch.","ar":"احذف خادمًا غير رئيسي وحدّد ما إذا كنت تريد الاحتفاظ بفرعه."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before deleting","ar":"قبل الحذف"},"blocks":[{"type":"note","tone":"warning","text":{"en":"Deletion permanently removes the environment’s active databases, files, and runtime logs. Download any backups you need first. This workflow cannot delete Production; cancelling the project is a separate action.","ar":"يحذف الإجراء قواعد البيئة وملفاتها وسجلات التشغيل الفعلية بصورة نهائية. نزّل النسخ التي تحتاجها أولًا. لا تحذف هذه الأداة Production؛ فإلغاء المشروع إجراء مستقل."}},{"type":"paragraph","text":{"en":"You need **Environment Deleter** for the target environment type. Deleting a server frees its reserved slot for reuse but does not release or refund the slot itself.","ar":"تحتاج دور **مسؤول حذف البيئات** لنوع البيئة المستهدفة. يحرّر حذف الخادم مكانه لإعادة الاستخدام، لكنه لا يلغي حجز السعة أو يعيد قيمتها بحد ذاته."}}]},{"id":"steps","title":{"en":"Delete safely","ar":"الحذف بأمان"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Select the Staging or Development environment and choose Delete.","ar":"اختر بيئة Staging أو Development ثم الحذف."},{"en":"Leave remote-branch deletion unchecked to keep the code branch. Select it only if the branch is no longer needed.","ar":"اترك حذف الفرع البعيد غير محدّد للاحتفاظ بالكود. حدّده فقط إذا لم تعد تحتاج الفرع."},{"en":"Type the exact environment name required by the confirmation dialog and confirm.","ar":"اكتب اسم البيئة المطلوب في نافذة التأكيد كما هو ثم أكّد."},{"en":"Wait for removal to finish. If branch deletion is rejected, inspect provider permissions, default/protected branch settings, and whether the branch still exists.","ar":"انتظر اكتمال الإزالة. إذا رُفض حذف الفرع فراجع صلاحيات المزوّد والفرع الافتراضي أو المحمي، وتأكد من أن الفرع ما زال موجودًا."}]}]}],"related":["environment-slots","reactivate","environment-create"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_core/models/saas_instance_repo.py","frontend/veltnex/src/pages/portal/Environments.tsx"]}]},{"id":"code","title":{"en":"Code and Deployment","ar":"الكود وDeployment"},"description":{"en":"Connect repositories, install dependencies, inspect builds, and upgrade only the required modules.","ar":"اربط المستودعات وثبّت المتطلبات وراجع البناء وحدّث الوحدات التي تحتاج إلى تحديث فقط."},"articles":[{"id":"custom-code","title":{"en":"Connect a Git repository","ar":"ربط مستودع Git"},"summary":{"en":"Configure project code, private credentials, and branch inheritance.","ar":"اضبط كود المشروع واعتماد المستودع الخاص وتوارث الفروع."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before you begin","ar":"قبل البدء"},"blocks":[{"type":"paragraph","text":{"en":"This is a hosting feature. Repository configuration requires **Project Administrator** or owner access and a running or stopped instance. A Deployment Operator can deploy existing configuration but cannot change the project repository settings. GitHub, GitLab, Bitbucket, and supported Gitea integrations have different provider permissions and API behavior.","ar":"هذه خاصية للاستضافة. يتطلب ضبط المستودع دور **مدير المشروع** أو حساب المالك وInstance تعمل أو متوقفة. يستطيع مسؤول Deployment نشر الإعداد الموجود، لكنه لا يغيّر إعدادات مستودع المشروع. تختلف صلاحيات المزوّد وسلوك API بين GitHub وGitLab وBitbucket وتكاملات Gitea المدعومة."}}]},{"id":"steps","title":{"en":"Connect and deploy","ar":"الربط وDeployment"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"On Production, open **Code & packages** and enter the Git clone URL and branch.","ar":"في Production، افتح **الكود والحزم** وأدخل عنوان استنساخ Git واسم الفرع."},{"en":"For a private repository, enter a token with access to the repository. Allow branch and webhook operations if you will use those workflows.","ar":"للمستودع الخاص، أدخل Token يملك الوصول إليه، مع السماح بعمليات الفروع وWebhooks إذا كنت ستستخدمها."},{"en":"Choose **Connect & deploy** or **Save & redeploy**. Wait for the build and rollout result.","ar":"اختر **ربط وDeployment** أو **حفظ وإعادة Deployment**، وانتظر نتيجة البناء والتشغيل."},{"en":"On subsequent edits, leaving the token blank preserves the stored token. Never paste credentials into a public issue or log excerpt.","ar":"عند تعديل الإعداد لاحقًا، يحافظ ترك Token فارغًا على القيمة المحفوظة. لا تنشر الاعتمادات في بلاغ عام أو مقتطف سجل."}]}]},{"id":"inherit","title":{"en":"Environment inheritance and disconnecting","ar":"التوارث وفصل المستودع"},"blocks":[{"type":"paragraph","text":{"en":"Child environments inherit the repository and credential from the project, with their own selected branch. Manage shared connection settings on Production. Disconnecting removes custom code from the runtime image; it does not uninstall modules from your databases. Installed modules can still require that code, so plan and test disconnection carefully.","ar":"ترث البيئات التابعة المستودع واعتماده من المشروع مع الفرع المختار لكل بيئة. تُدار إعدادات الاتصال المشتركة في Production. فصل المستودع يزيل الكود المخصص من صورة التشغيل، لكنه لا يلغي تثبيت وحداته في قواعد البيانات. قد تظل الوحدات المثبتة بحاجة إلى الكود؛ لذا خطّط للفصل واختبر أثره بعناية."}}]}],"related":["python-dependencies","deployment-history","environment-create"],"sources":["frontend/veltnex/src/pages/portal/Code.tsx","control-plane/saas_website/controllers/api.py","control-plane/saas_core/models/saas_instance_repo.py"]},{"id":"python-dependencies","title":{"en":"Manage Python dependencies","ar":"إدارة متطلبات Python"},"summary":{"en":"Declare reproducible package requirements in your repository.","ar":"حدّد متطلبات حزم قابلة لإعادة البناء داخل مستودعك."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"file","title":{"en":"Use requirements.txt","ar":"استخدام requirements.txt"},"blocks":[{"type":"paragraph","text":{"en":"Python dependencies come from your repository’s `requirements.txt`, not a manually entered package list in the control panel. Commit the file and deploy the affected branch. Pin compatible versions for repeatable builds. The build uses validation and cached dependency layers; a package change can take longer than a code-only rebuild.","ar":"تأتي متطلبات Python من ملف `requirements.txt` في مستودعك، وليس من قائمة حزم تُدخل يدويًا في لوحة التحكم. أضف الملف إلى Git ثم نفّذ Deployment للفرع المعني. ثبّت أرقام إصدارات متوافقة لإعادة البناء بشكل متوقع. يتحقق البناء من المتطلبات ويستخدم طبقات الحزم المخزّنة مؤقتًا؛ وقد يستغرق تغيير الحزم وقتًا أطول من تغيير الكود وحده."}},{"type":"code","language":"text","code":"phonenumbers==9.0.40\\n# Add only dependencies needed by your modules."}]},{"id":"failures","title":{"en":"Resolve dependency failures","ar":"معالجة إخفاق المتطلبات"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Read the failed build output to identify the package, version, or validation error.","ar":"اقرأ مخرجات البناء المخفق لتحديد الحزمة أو الإصدار أو خطأ التحقق."},{"en":"Check compatibility with the selected Odoo and Python runtime, and confirm the package is available from the supported package source.","ar":"تحقق من التوافق مع Odoo وPython المختارين ومن إتاحة الحزمة في مصدر الحزم المدعوم."},{"en":"Correct and commit requirements.txt, then push the branch or request redeployment.","ar":"صحّح requirements.txt وأضفه إلى Git، ثم ادفع الفرع أو اطلب إعادة Deployment."}]},{"type":"paragraph","text":{"en":"Do not use the browser terminal as a persistent package-installation method. Runtime Containers are replaced by deployments; durable dependencies belong in the image build. A requirements file does not provision arbitrary operating-system packages.","ar":"لا تعتمد على تثبيت الحزم في Terminal كإعداد دائم. يستبدل Deployment الـ Containers، ولذلك يجب تضمين المتطلبات الدائمة في بناء الصورة. ملف المتطلبات لا يوفّر أي حزمة لنظام التشغيل تلقائيًا."}}]}],"related":["custom-code","deployment-troubleshooting"],"sources":["frontend/veltnex/src/pages/portal/Code.tsx","control-plane/saas_core/templates/build"]},{"id":"deployment-history","title":{"en":"Build, redeploy, and inspect Deployment history","ar":"البناء وإعادة Deployment ومراجعة السجل"},"summary":{"en":"Follow build stages, triggers, outcomes, and retention.","ar":"تابع مراحل البناء ومصدر الطلب والنتيجة وسياسة الاحتفاظ."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"workflow","title":{"en":"Deployment workflow","ar":"مسار Deployment"},"blocks":[{"type":"paragraph","text":{"en":"Deployments can originate from initial launch, a Git push webhook, manual redeployment, a merge, or rollback. Automatic pushes require a working provider webhook and the matching repository branch. Check provider webhook delivery if a push does not appear. Manual redeployment requires **Deployment Operator** access.","ar":"قد يبدأ Deployment من الإطلاق الأول أو Webhook لدفع Git أو طلب يدوي أو دمج أو تراجع. يتطلب الدفع التلقائي Webhook يعمل لدى المزوّد وفرعًا مطابقًا للمستودع. إذا لم يظهر الدفع، راجع تسليم Webhook لدى المزوّد. تتطلب إعادة Deployment اليدوية دور **مسؤول Deployment**."}},{"type":"table","headers":[{"en":"Stage","ar":"المرحلة"},{"en":"What is happening","ar":"ما الذي يجري؟"}],"rows":[[{"en":"Queued","ar":"Queued"},{"en":"Waiting for a build slot or serialized work to finish.","ar":"انتظار مكان للبناء أو اكتمال العمل المتعارض."}],[{"en":"Building image","ar":"Building image"},{"en":"Fetching code, validating dependencies, and preparing the runtime image.","ar":"جلب الكود والتحقق من المتطلبات وتجهيز صورة التشغيل."}],[{"en":"Upgrading modules & rolling out","ar":"Upgrading modules & rolling out"},{"en":"Applying needed Odoo upgrades and checking the new application runtime.","ar":"تطبيق تحديثات Odoo اللازمة والتحقق من تشغيل النسخة الجديدة."}],[{"en":"Success / Failed","ar":"Success / Failed"},{"en":"The final result; inspect details before another change.","ar":"النتيجة النهائية؛ راجع التفاصيل قبل إجراء تغيير آخر."}]]}]},{"id":"inspect","title":{"en":"Inspect a build","ar":"مراجعة عملية البناء"},"blocks":[{"type":"paragraph","text":{"en":"Select the environment and open its Deployment history. Review the trigger, branch, commit, author, time, stage, and result. **Project Viewer** can view build metadata. **Logs Viewer** is required to read deployment output. The current image continues serving during image preparation where possible, but rollout and database changes can still affect users.","ar":"اختر البيئة وافتح سجل Deployment. راجع المصدر والفرع وCommit والكاتب والوقت والمرحلة والنتيجة. يتيح **قارئ المشروع** عرض بيانات البناء، بينما تتطلب مخرجاته دور **قارئ السجلات**. تستمر الصورة الحالية في خدمة الطلبات أثناء التجهيز عندما يكون ذلك ممكنًا، لكن التشغيل الجديد وتغييرات القاعدة قد تؤثر على المستخدمين."}}]},{"id":"retention","title":{"en":"History retention","ar":"الاحتفاظ بالسجل"},"blocks":[{"type":"paragraph","text":{"en":"History is bounded, not permanent. Defaults are 30 days and 50 completed records per environment, configurable by the platform. Active work, current/previous successful images, and upgrade baselines can be protected beyond ordinary cleanup. Download important error output before it is removed; build-history retention is separate from backups and registry-image retention.","ar":"الاحتفاظ بالسجل محدود وليس دائمًا. الإعداد الافتراضي 30 يومًا و50 سجلًا مكتملًا لكل بيئة، ويمكن للمنصة تعديله. قد تُحمى العمليات الجارية والصورتان الحالـية والسابقة الناجحتان وبيانات أساس التحديث من التنظيف المعتاد. احفظ مخرجات الأخطاء المهمة قبل حذفها؛ فالاحتفاظ بسجل البناء مستقل عن النسخ الاحتياطية وصور Registry."}}]}],"related":["module-upgrades","deployment-rollback","deployment-troubleshooting"],"sources":["control-plane/saas_core/models/saas_build.py","control-plane/saas_core/models/saas_instance_build.py","frontend/veltnex/src/components/DeploymentHistory.tsx"]},{"id":"module-upgrades","title":{"en":"Understand selective Odoo module upgrades","ar":"فهم تحديث وحدات Odoo بشكل انتقائي"},"summary":{"en":"Distinguish code deployment, module upgrades, and major-version migration.","ar":"ميّز بين Deployment للكود وتحديث الوحدات والانتقال إلى إصدار رئيسي جديد."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"selection","title":{"en":"How modules are selected","ar":"كيف تُختار الوحدات؟"},"blocks":[{"type":"paragraph","text":{"en":"The build compares repository module upgrade inputs with the last successful baseline. Relevant inputs include manifest version/dependencies/loaded data, model fields and schema metadata, XML or CSV loaded by the manifest, and migration files. Ordinary Python method-body and static asset changes generally do not request a database upgrade by themselves.","ar":"يقارن البناء المدخلات المؤثرة في تحديث وحدات المستودع بآخر أساس ناجح. تشمل هذه المدخلات الإصدار والاعتماديات والبيانات المحمّلة في Manifest، وحقول النماذج وتعريفات البنية، وملفات XML أو CSV المحمّلة، وملفات الترحيل. عادةً لا يستدعي تغيير منطق دالة Python أو الملفات الثابتة تحديث قاعدة البيانات وحده."}},{"type":"paragraph","text":{"en":"Selected repository modules are passed by name; the pipeline does not request the blanket `all` upgrade. Without a previous baseline, all detected repository modules may be selected. Odoo skips uninstalled modules; deployment is not a replacement for installing a new application. Odoo dependencies and migration logic can still cause related database work.","ar":"تُمرر أسماء وحدات المستودع المختارة دون طلب التحديث الشامل `all`. عند غياب أساس سابق قد تُختار كل وحدات المستودع المكتشفة. يتجاوز Odoo الوحدات غير المثبتة؛ لذا لا يحل Deployment محل تثبيت تطبيق جديد. وقد تؤدي اعتماديات Odoo ومنطق الترحيل إلى أعمال إضافية مرتبطة بالقاعدة."}}]},{"id":"manual","title":{"en":"Request a manual upgrade","ar":"طلب تحديث يدوي"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Back up the database and verify the module code is already deployed.","ar":"انسخ قاعدة البيانات احتياطيًا وتأكد من وصول كود الوحدات إلى البيئة."},{"en":"In Databases, choose the module-upgrade action for the required database.","ar":"من قواعد البيانات اختر إجراء تحديث الوحدات للقاعدة المطلوبة."},{"en":"Enter explicit technical module names such as `sale, stock_account`. Use **Deployment Operator** access and follow the operation report.","ar":"أدخل أسماء الوحدات التقنية صراحة مثل `sale, stock_account`. استخدم صلاحية **مسؤول Deployment** وتابع تقرير العملية."}]},{"type":"note","tone":"warning","text":{"en":"Module upgrades can change schema and records. They are different from changing the Odoo major version and should be tested in Staging before Production.","ar":"قد يغيّر تحديث الوحدات بنية القاعدة والسجلات. وهو مستقل عن تغيير إصدار Odoo الرئيسي، وينبغي اختباره في Staging قبل Production."}}]}],"related":["environment-create","ondemand-backups","deployment-rollback"],"sources":["control-plane/saas_core/templates/build/module_fingerprint.py","control-plane/saas_core/models/saas_instance_build.py","control-plane/saas_core/models/saas_instance_db_operation.py"]},{"id":"deployment-rollback","title":{"en":"Roll back a Deployment","ar":"التراجع عن Deployment"},"summary":{"en":"Return to a previous runtime image while treating database changes separately.","ar":"ارجع إلى صورة تشغيل سابقة مع التعامل مع تغييرات القاعدة بشكل مستقل."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"behavior","title":{"en":"What rollback does","ar":"ما الذي يفعله التراجع؟"},"blocks":[{"type":"paragraph","text":{"en":"The backend supports rollback to a previously successful immutable runtime image when an eligible image is retained. The current customer portal does not expose a rollback button; contact support to assess an eligible image. It does not undo schema changes, module migrations, or data written since the earlier deployment.","ar":"يدعم Backend التراجع إلى صورة تشغيل ثابتة سابقة وناجحة عند الاحتفاظ بصورة مؤهلة. لا تعرض لوحة العميل الحالية زر تراجع؛ تواصل مع الدعم لتقييم صورة مؤهلة. لا يعكس التراجع تغييرات البنية أو ترحيل الوحدات أو البيانات التي كُتبت بعد Deployment السابق."}}]},{"id":"safe","title":{"en":"Plan a safe rollback","ar":"التخطيط للتراجع الآمن"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Identify the previous successful commit/image and read the failure that triggered rollback.","ar":"حدّد Commit أو الصورة السابقة الناجحة واقرأ سبب الإخفاق."},{"en":"Confirm the older code can run against the current database. If it cannot, plan a compatible database restore with support.","ar":"تحقق من قدرة الكود الأقدم على العمل مع القاعدة الحالية. إذا لم يتوافق، خطّط مع الدعم لاستعادة قاعدة مناسبة."},{"en":"Request rollback through support and agree on the target image and recovery plan. Monitor the resulting rollout and application behavior.","ar":"اطلب التراجع من الدعم واتفق على الصورة المستهدفة وخطة الاستعادة. تابع التشغيل الناتج وسلوك التطبيق."}]}]}],"related":["restore","module-upgrades","deployment-history"],"sources":["control-plane/saas_core/models/saas_instance_build.py"]}]},{"id":"databases","title":{"en":"Databases","ar":"قواعد البيانات"},"description":{"en":"Create, open, duplicate, restore, and remove Odoo databases with clear safety checks.","ar":"أنشئ قواعد Odoo وافتحها وانسخها واستعدها واحذفها مع فهم ضوابط الأمان."},"articles":[{"id":"manage-databases","title":{"en":"Create and open a database","ar":"إنشاء قاعدة بيانات وفتحها"},"summary":{"en":"Initialize your application and understand the Production database limit.","ar":"جهّز تطبيقك وافهم حد قواعد البيانات في Production."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"limits","title":{"en":"Database limits","ar":"حدود قواعد البيانات"},"blocks":[{"type":"paragraph","text":{"en":"Production hosting allows one customer database. You can delete it and create another, or restore into it with replacement. Staging and Development do not use this one-database limit, but they share their environment’s storage allowance. Existing legacy extra databases are not proof that creating another is allowed.","ar":"تسمح استضافة Production بقاعدة بيانات واحدة للعميل. يمكنك حذفها وإنشاء أخرى أو استعادتها مع الاستبدال. لا يطبق هذا الحد على Staging وDevelopment، لكن قواعدهما تستهلك سعة بيئتها. وجود قواعد إضافية من إعداد قديم لا يعني السماح بإنشاء قاعدة أخرى."}}]},{"id":"create","title":{"en":"Create the database","ar":"خطوات الإنشاء"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open a running hosting environment’s **Databases** tab with **Database Creator** access.","ar":"افتح تبويب **قواعد البيانات** في بيئة استضافة تعمل، بصلاحية **مسؤول إنشاء قواعد البيانات**."},{"en":"Choose Create database and enter a lowercase name, administrator login, and password. The portal currently initializes new databases in English; configure the application language inside Odoo afterward.","ar":"اختر إنشاء قاعدة بيانات وأدخل اسمًا بحروف صغيرة واسم دخول المسؤول وكلمة مروره. تُنشئ لوحة التحكم القاعدة بالإنجليزية حاليًا؛ ويمكن ضبط لغة التطبيق داخل Odoo لاحقًا."},{"en":"Review the full prefixed name and confirm. Wait until the create operation finishes and the database appears.","ar":"راجع الاسم الكامل مع البادئة وأكّد، ثم انتظر اكتمال الإنشاء وظهور القاعدة."},{"en":"Use Open from the database row and sign in with its administrator credentials. A VELTNEX password does not automatically become the database password.","ar":"استخدم الفتح من صف القاعدة وسجّل ببيانات مسؤولها. كلمة مرور VELTNEX لا تصبح تلقائيًا كلمة مرور القاعدة."}]}]},{"id":"names","title":{"en":"Naming rules","ar":"قواعد التسمية"},"blocks":[{"type":"paragraph","text":{"en":"Use at least 3 characters, start with a letter, and use lowercase letters, digits, underscores, or hyphens. Do not end with an underscore/hyphen or repeat either consecutively. The full database name, including the environment prefix, must fit PostgreSQL’s 63-character name limit. The prefix keeps databases associated with the correct environment.","ar":"استخدم 3 أحرف على الأقل، وابدأ بحرف، واستعمل حروفًا صغيرة وأرقامًا وشرطة سفلية أو واصلة. لا تنهِ الاسم بشرطة ولا تكرر الشرطات المتتابعة. يجب أن يتسع الاسم الكامل مع بادئة البيئة ضمن حد PostgreSQL البالغ 63 حرفًا. تربط البادئة القاعدة بالبيئة الصحيحة."}}]}],"related":["database-restore","database-access","database-delete"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_website/controllers/api.py","frontend/veltnex/src/pages/portal/Databases.tsx"]},{"id":"database-duplicate","title":{"en":"Duplicate a database","ar":"إنشاء نسخة مطابقة من قاعدة البيانات"},"summary":{"en":"Create an independent copy where capacity allows it.","ar":"أنشئ نسخة مستقلة عندما تسمح السعة بذلك."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Requirements","ar":"المتطلبات"},"blocks":[{"type":"paragraph","text":{"en":"Duplication is a hosting operation on a running environment. You need **Database Creator** and **Database Backup Downloader**, because the operation copies source data. The Production one-database rule normally prevents duplicating an existing Production database on the same instance; use a Staging or Development target through the copy workflow instead.","ar":"إنشاء النسخة المطابقة إجراء للاستضافة في بيئة تعمل. تحتاج **مسؤول إنشاء قواعد البيانات** و**مسؤول تنزيل النسخ الاحتياطية** لأن العملية تنسخ بيانات المصدر. يمنع حد قاعدة Production الواحدة عادةً إنشاء نسخة إضافية على Instance نفسها؛ استخدم بدلًا من ذلك النسخ إلى Staging أو Development."}}]},{"id":"steps","title":{"en":"Duplicate","ar":"خطوات إنشاء النسخة"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Select the source database and choose Duplicate.","ar":"اختر قاعدة المصدر ثم إنشاء نسخة مطابقة."},{"en":"Enter a new valid name and verify enough storage is available.","ar":"أدخل اسمًا جديدًا صالحًا وتأكد من وجود سعة تخزين كافية."},{"en":"Confirm and wait for the background operation to finish before opening the copy.","ar":"أكّد وانتظر اكتمال العملية في الخلفية قبل فتح النسخة."}]},{"type":"note","tone":"warning","text":{"en":"The copied database has its own data after creation. Check scheduled tasks, email, payment providers, and external integrations before using it for testing; cloning is not a guarantee of neutralization.","ar":"تصبح للنسخة بيانات مستقلة بعد الإنشاء. راجع المهام المجدولة والبريد ومزوّدي الدفع والتكاملات الخارجية قبل استخدامها للاختبار؛ فنسخ القاعدة لا يضمن تعطيل اتصالاتها الفعلية."}}]}],"related":["environment-copy","manage-databases","ondemand-backups"],"sources":["control-plane/saas_core/models/saas_instance_db_operation.py","control-plane/saas_iam/models/integration.py"]},{"id":"database-restore","title":{"en":"Restore a database from a local backup","ar":"استعادة قاعدة بيانات من نسخة محلية"},"summary":{"en":"Upload an Odoo backup and restore into a new or existing database.","ar":"ارفع نسخة Odoo واستعدها إلى قاعدة جديدة أو موجودة."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before you begin","ar":"قبل البدء"},"blocks":[{"type":"paragraph","text":{"en":"Use a running hosting environment and **Database Restore Operator** access. Choose a backup compatible with the environment’s Odoo version and installed code. The upload dialog accepts supported Odoo backup archives; prefer an Odoo ZIP that includes the filestore for attachments. A raw database dump alone does not include attachments.","ar":"استخدم بيئة استضافة تعمل ودور **مسؤول استعادة قواعد البيانات**. اختر نسخة تتوافق مع إصدار Odoo والكود المثبت في البيئة. تقبل نافذة الرفع أرشيفات نسخ Odoo المدعومة؛ ويفضل ZIP يحتوي مجلد المرفقات. تفريغ قاعدة البيانات وحده لا يشمل المرفقات."}}]},{"id":"steps","title":{"en":"Upload and restore","ar":"الرفع والاستعادة"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Choose Restore in Databases, select the backup file, and choose a new database name or replacement of an existing database.","ar":"اختر الاستعادة من قواعد البيانات وحدّد الملف، ثم اسم قاعدة جديدة أو استبدال قاعدة موجودة."},{"en":"In Production, replace the existing customer database or delete it before restoring another name. For replacement, type the exact full target name required by the dialog.","ar":"في Production استبدل قاعدة العميل الموجودة، أو احذفها قبل الاستعادة باسم آخر. عند الاستبدال اكتب اسم الهدف الكامل المطلوب في النافذة كما هو."},{"en":"Keep the browser open for upload. The file goes directly to object storage and shows upload progress.","ar":"أبقِ المتصفح مفتوحًا أثناء الرفع. ينتقل الملف مباشرة إلى التخزين وتظهر نسبة التقدم."},{"en":"After upload completes, the platform validates the archive and starts the background restore. Follow the database operation until it completes or shows an error.","ar":"بعد اكتمال الرفع تتحقق المنصة من الأرشيف وتبدأ الاستعادة في الخلفية. تابع العملية حتى تكتمل أو تعرض خطأ."},{"en":"Open the restored database with its original application credentials. Reset its administrator password if required and permitted.","ar":"افتح القاعدة المستعادة ببيانات دخول التطبيق الأصلية، وأعد تعيين كلمة مرور المسؤول عند الحاجة إذا كنت تملك الصلاحية."}]}]},{"id":"safety","title":{"en":"Replacement and compatibility","ar":"الاستبدال والتوافق"},"blocks":[{"type":"note","tone":"warning","text":{"en":"Replacement destroys the target’s current data. Download a fresh target backup before confirming. Archive validation cannot guarantee that every custom module, external integration, or major-version mismatch will work after restore.","ar":"يمحو الاستبدال بيانات الهدف الحالية. نزّل نسخة جديدة من الهدف قبل التأكيد. التحقق من الأرشيف لا يضمن توافق كل وحدة مخصصة أو تكامل خارجي أو اختلاف في الإصدار الرئيسي."}}]}],"related":["ondemand-backups","database-access","database-troubleshooting"],"sources":["control-plane/saas_website/controllers/api.py","control-plane/saas_core/models/saas_instance.py","frontend/veltnex/src/pages/portal/Databases.tsx"]},{"id":"database-access","title":{"en":"Database Manager and administrator passwords","ar":"مدير قواعد البيانات وكلمات مرور المسؤول"},"summary":{"en":"Open authorized management tools and separate platform access from Odoo access.","ar":"افتح أدوات الإدارة المصرّح بها وميّز صلاحيات المنصة عن صلاحيات Odoo."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"manager","title":{"en":"Open Database Manager","ar":"فتح مدير قواعد البيانات"},"blocks":[{"type":"paragraph","text":{"en":"The owner or a platform administrator can open **Database Manager** from the environment’s Databases page. The button generates authorized access to Odoo’s own manager without revealing the master password. Teammates, including Project Administrators, use the permission-checked portal database actions instead; no fixed teammate role grants unrestricted Database Manager access.","ar":"يستطيع المالك أو مسؤول المنصة فتح **مدير قواعد البيانات** من صفحة قواعد بيانات البيئة. ينشئ الزر وصولًا مصرحًا به إلى مدير Odoo دون كشف كلمة المرور الرئيسية. يستخدم أعضاء الفريق، بمن فيهم مديرو المشاريع، إجراءات لوحة التحكم التي تتحقق من الصلاحيات؛ ولا يمنح أي دور ثابت للفريق وصولًا غير مقيّد إلى مدير قواعد البيانات."}},{"type":"paragraph","text":{"en":"Use the control-panel button rather than bookmarking or sharing the manager link. The public root of a hosting site with a customer database serves the application; an empty site shows a no-database message. Database-management authorization is separate from visitors opening the customer’s website.","ar":"استخدم زر لوحة التحكم بدل حفظ رابط المدير أو مشاركته. يفتح العنوان الرئيسي لموقع الاستضافة التطبيق عند وجود قاعدة للعميل، ويعرض رسالة عدم وجود قاعدة عندما يكون فارغًا. صلاحية إدارة القواعد مستقلة عن زيارة عملاء صاحب الموقع لموقعه."}}]},{"id":"password","title":{"en":"Reset the database administrator password","ar":"إعادة تعيين كلمة مرور مسؤول القاعدة"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"With **Database Access Administrator** access, choose Reset password for the required database.","ar":"بدور **مسؤول وصول قواعد البيانات**، اختر إعادة تعيين كلمة المرور للقاعدة المطلوبة."},{"en":"Set a new password that meets the dialog’s requirements and save it securely.","ar":"حدّد كلمة مرور تستوفي متطلبات النافذة واحفظها بأمان."},{"en":"Use the administrator login displayed for the database and the new password to sign in to Odoo.","ar":"استخدم اسم دخول المسؤول المعروض للقاعدة وكلمة المرور الجديدة للدخول إلى Odoo."}]},{"type":"paragraph","text":{"en":"This changes the database administrator’s application password. It does not change your VELTNEX login, the PostgreSQL connection credential, or other Odoo users.","ar":"يغيّر الإجراء كلمة مرور مسؤول التطبيق في القاعدة، وليس دخول VELTNEX أو اعتماد اتصال PostgreSQL أو كلمات مرور مستخدمي Odoo الآخرين."}}]}],"related":["iam-roles","manage-databases","password-recovery"],"sources":["control-plane/saas_core/models/saas_instance.py","compute/operator/internal/resources/platformaddons/saas_tenant_dbm/controllers.py","control-plane/saas_iam/roles.py"]},{"id":"database-delete","title":{"en":"Delete and replace a database","ar":"حذف قاعدة بيانات واستبدالها"},"summary":{"en":"Understand confirmation, irreversible data loss, and creating another database.","ar":"افهم التأكيد وفقدان البيانات وإنشاء قاعدة بديلة."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before deleting","ar":"قبل الحذف"},"blocks":[{"type":"note","tone":"warning","text":{"en":"Deleting removes the selected database and its associated application files. This cannot be undone by cancelling the dialog afterward. Download and test a usable backup first; deletion is not a backup operation.","ar":"يزيل الحذف القاعدة المختارة وملفات التطبيق المرتبطة بها. لا يمكن التراجع عنه بإغلاق النافذة بعد التنفيذ. نزّل نسخة قابلة للاستخدام واختبرها أولًا؛ فالحذف ليس إجراء نسخ احتياطي."}}]},{"id":"steps","title":{"en":"Delete","ar":"خطوات الحذف"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Use **Database Deleter** access on a running hosting environment.","ar":"استخدم دور **مسؤول حذف قواعد البيانات** في بيئة استضافة تعمل."},{"en":"Choose Delete for the database and type its exact full name to confirm.","ar":"اختر الحذف للقاعدة واكتب اسمها الكامل كما هو للتأكيد."},{"en":"Wait for the operation to complete. In Production, you can then create a replacement database or restore another one within the one-database limit.","ar":"انتظر اكتمال العملية. يمكنك بعدها في Production إنشاء قاعدة بديلة أو استعادة أخرى ضمن حد القاعدة الواحدة."}]}]},{"id":"scope","title":{"en":"What stays in place","ar":"ما الذي يبقى؟"},"blocks":[{"type":"paragraph","text":{"en":"Deleting a database does not cancel the instance, free a reserved environment slot, remove its Git branch, or stop subscription billing. An empty hosting site displays the no-database page until another customer database is created or restored.","ar":"حذف القاعدة لا يلغي Instance ولا يحرّر مكان البيئة المحجوز ولا يحذف فرع Git ولا يوقف فوترة الاشتراك. يعرض الموقع الفارغ رسالة عدم وجود قاعدة إلى أن تُنشأ قاعدة عميل أخرى أو تُستعاد."}}]}],"related":["ondemand-backups","database-restore","reactivate"],"sources":["frontend/veltnex/src/pages/portal/Databases.tsx","control-plane/saas_core/models/saas_instance_db_operation.py"]}]},{"id":"backups","title":{"en":"Backups and recovery","ar":"النسخ الاحتياطي والاستعادة"},"description":{"en":"Choose database exports or full-instance snapshots and plan recovery before changes.","ar":"اختر تصدير قاعدة أو لقطة كاملة وخطّط للاستعادة قبل التغييرات."},"articles":[{"id":"daily-backups","title":{"en":"Enable automatic daily snapshots","ar":"تفعيل اللقطات اليومية التلقائية"},"summary":{"en":"Understand coverage, monthly billing, retention, and payment pauses.","ar":"تعرّف على المحتويات والفوترة الشهرية والاحتفاظ والتوقف بسبب الدفع."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"coverage","title":{"en":"Coverage and retention","ar":"المحتويات والاحتفاظ"},"blocks":[{"type":"paragraph","text":{"en":"Daily snapshots are an optional paid add-on for eligible non-trial instances. Hosting snapshots capture full-instance data and recovery metadata, including databases and files. They are different from a one-off backup of one database. The default policy keeps 7 recent daily snapshots; actual capture times and available copies depend on successful scheduled runs and platform settings.","ar":"اللقطات اليومية إضافة مدفوعة اختيارية للـ Instances المؤهلة غير التجريبية. تشمل لقطات الاستضافة بيانات البيئة الكاملة ومعلومات الاستعادة، بما فيها القواعد والملفات. وهي مختلفة عن نسخة يدوية لقاعدة واحدة. تحتفظ السياسة الافتراضية بـ 7 لقطات يومية حديثة؛ ويتوقف توقيت الالتقاط والنسخ المتاحة على نجاح المهام المجدولة وإعدادات المنصة."}}]},{"id":"enable","title":{"en":"Enable and monitor","ar":"التفعيل والمتابعة"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"As the owner, open **Snapshots** and choose to enable daily snapshots.","ar":"بصفتك المالك، افتح **اللقطات** واختر تفعيل اللقطات اليومية."},{"en":"Review the price and checkout. The hosting charge is based on used data and is re-evaluated on monthly backup renewal, separately from the main subscription cycle.","ar":"راجع السعر والدفع. تعتمد تكلفة الاستضافة على البيانات المستخدمة، وتُعاد مراجعتها عند التجديد الشهري للنسخ، بشكل مستقل عن دورة الاشتراك الرئيسية."},{"en":"After payment and activation, check the latest successful snapshot date. The first copy appears after its scheduled run completes.","ar":"بعد الدفع والتفعيل، راجع تاريخ أحدث لقطة ناجحة. تظهر النسخة الأولى بعد اكتمال المهمة المجدولة."}]}]},{"id":"payment","title":{"en":"Payment and availability","ar":"الدفع والإتاحة"},"blocks":[{"type":"paragraph","text":{"en":"An unpaid backup invoice pauses daily capture after its backup grace period (currently 3 days after the due date), without treating that optional charge as a main-subscription suspension. Capture resumes after settlement. Existing copies remain subject to retention. Backup access and restore require a running instance and the appropriate roles.","ar":"توقف فاتورة النسخ غير المدفوعة الالتقاط اليومي بعد مهلتها، وهي حاليًا 3 أيام من تاريخ الاستحقاق، دون اعتبار هذه الإضافة سببًا لتعليق الاشتراك الرئيسي. يُستأنف الالتقاط بعد التسوية، وتظل النسخ الموجودة خاضعة للاحتفاظ. يتطلب الوصول والاستعادة Instance تعمل والصلاحيات المناسبة."}}]}],"related":["restore","ondemand-backups","auto-renew"],"sources":["frontend/veltnex/src/pages/portal/Backups.tsx","control-plane/saas_billing/models/saas_instance.py","control-plane/saas_core/models/saas_instance_backup.py"]},{"id":"restore","title":{"en":"Restore a full-instance snapshot","ar":"استعادة لقطة كاملة لـ Instance"},"summary":{"en":"Replace current data with a previous snapshot and verify recovery.","ar":"استبدل البيانات الحالية بلقطة سابقة وتحقق من الاستعادة."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Before you begin","ar":"قبل البدء"},"blocks":[{"type":"paragraph","text":{"en":"Use a running instance, an available completed snapshot, and **Database Restore Operator** access. Review the snapshot’s date and environment. Snapshot restoration is an instance-wide operation; use local database restore when only one database should be replaced.","ar":"استخدم Instance تعمل ولقطة مكتملة متاحة ودور **مسؤول استعادة قواعد البيانات**. راجع تاريخ اللقطة وبيئتها. استعادة اللقطة تشمل Instance بالكامل؛ استخدم استعادة قاعدة محلية إذا أردت استبدال قاعدة واحدة فقط."}}]},{"id":"steps","title":{"en":"Restore and verify","ar":"الاستعادة والتحقق"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open Snapshots and choose Restore on the desired copy.","ar":"افتح اللقطات واختر الاستعادة للنسخة المطلوبة."},{"en":"Read the replacement warning and type the exact name requested in the confirmation dialog.","ar":"اقرأ تنبيه الاستبدال واكتب الاسم المطلوب في نافذة التأكيد كما هو."},{"en":"Start restore and wait while the instance enters provisioning. The platform attempts a fresh pre-restore safety snapshot first.","ar":"ابدأ الاستعادة وانتظر أثناء انتقال Instance إلى التجهيز. تحاول المنصة أخذ لقطة أمان جديدة قبل الاستعادة."},{"en":"After the instance returns to running, check database availability, attachments, application login, and critical workflows.","ar":"بعد العودة إلى التشغيل، تحقق من القواعد والمرفقات وتسجيل الدخول والوظائف الأساسية."}]}]},{"id":"safety","title":{"en":"Recovery consequences","ar":"أثر الاستعادة"},"blocks":[{"type":"note","tone":"warning","text":{"en":"The chosen snapshot replaces current databases, files, and captured configuration. Later changes are lost unless preserved elsewhere. A safety snapshot is not a substitute for a backup you have already downloaded and verified. Coordinate downtime and integration replay with your team.","ar":"تستبدل اللقطة المختارة القواعد والملفات والإعدادات التي شملها الالتقاط. تُفقد التغييرات اللاحقة ما لم تُحفظ في مكان آخر. لقطة الأمان لا تُغني عن نسخة نزّلتها وتحققت منها مسبقًا. نسّق توقف الخدمة وإعادة معالجة التكاملات مع فريقك."}}]}],"related":["daily-backups","database-restore","database-troubleshooting"],"sources":["control-plane/saas_website/controllers/api.py","control-plane/saas_core/models/saas_instance_backup.py","frontend/veltnex/src/pages/portal/Backups.tsx"]},{"id":"ondemand-backups","title":{"en":"Create and download a database backup","ar":"إنشاء نسخة احتياطية لقاعدة وتنزيلها"},"summary":{"en":"Export one database with the correct format and download permission.","ar":"صدّر قاعدة واحدة بالصيغة المناسبة وصلاحية التنزيل المطلوبة."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"formats","title":{"en":"Choose a backup format","ar":"اختيار الصيغة"},"blocks":[{"type":"table","headers":[{"en":"Format","ar":"الصيغة"},{"en":"Contents","ar":"المحتويات"}],"rows":[[{"en":"ZIP","ar":"ZIP"},{"en":"Odoo database export with filestore attachments. Prefer it for moving the application with files.","ar":"تصدير قاعدة Odoo مع ملفات المرفقات. يُفضّل لنقل التطبيق بملفاته."}],[{"en":"Dump","ar":"Dump"},{"en":"PostgreSQL database dump without the filestore. Preserve attachment files separately if needed.","ar":"تفريغ قاعدة PostgreSQL دون مجلد المرفقات. احتفظ بالمرفقات بشكل مستقل إذا احتجتها."}]]}]},{"id":"steps","title":{"en":"Back up and download","ar":"النسخ والتنزيل"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"With **Database Backup Operator**, choose Backup for the database on a running hosting environment.","ar":"بدور **مسؤول النسخ الاحتياطي لقواعد البيانات**، اختر النسخ للقاعدة في بيئة استضافة تعمل."},{"en":"Select the available format and wait for preparation to complete.","ar":"حدّد الصيغة المتاحة وانتظر اكتمال التجهيز."},{"en":"Use **Database Backup Downloader** access to download the completed copy. Creation permission alone does not grant download.","ar":"استخدم دور **مسؤول تنزيل النسخ الاحتياطية** لتنزيل النسخة المكتملة. صلاحية الإنشاء لا تمنح التنزيل وحدها."},{"en":"Store the file securely and test restoration in an appropriate non-production environment.","ar":"احفظ الملف بأمان واختبر استعادته في بيئة مناسبة غير Production."}]}]},{"id":"links","title":{"en":"Links and retention","ar":"الروابط والاحتفاظ"},"blocks":[{"type":"paragraph","text":{"en":"Downloads go through an authorization-checked portal link and can redirect to expiring storage access. Request a new download from the page if the link expires. On-demand exports and temporary restore/copy files have cleanup policies; do not use the portal as permanent backup storage. Removing access cannot retract an already downloaded file or immediately revoke a storage URL already issued.","ar":"تمر التنزيلات عبر رابط في اللوحة يتحقق من الصلاحية، وقد يحوّلك إلى وصول مؤقت للتخزين. اطلب تنزيلًا جديدًا من الصفحة إذا انتهى الرابط. للنسخ اليدوية وملفات الاستعادة والنسخ المؤقتة سياسات تنظيف؛ فلا تعتمد على اللوحة كمخزن دائم. إلغاء الوصول لا يسترجع ملفًا نُزّل بالفعل، ولا يلغي فورًا رابط تخزين صدر سابقًا."}}]}],"related":["database-restore","iam-roles","restore"],"sources":["control-plane/saas_core/models/saas_instance_backup.py","control-plane/saas_iam/controllers/api.py","frontend/veltnex/src/pages/portal/Databases.tsx"]}]},{"id":"iam","title":{"en":"Team and permissions","ar":"الفريق والصلاحيات"},"description":{"en":"Manage teammates, fixed roles, groups, and environment-scoped access.","ar":"أدر أعضاء الفريق والأدوار الثابتة والمجموعات والوصول المحدد بالبيئة."},"articles":[{"id":"iam-overview","title":{"en":"Team and permissions overview","ar":"نظرة عامة على الفريق والصلاحيات"},"summary":{"en":"Understand ownership, principals, grants, and least-privilege access.","ar":"افهم الملكية والجهات الممنوحة والأدوار والوصول بالقدر المطلوب."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"model","title":{"en":"Access model","ar":"نموذج الوصول"},"blocks":[{"type":"paragraph","text":{"en":"A grant combines a teammate or team group, one or several projects belonging to the same customer, one or several fixed roles, and Production, Staging, Development, or all environments. Roles combine within their assigned scopes. Customers cannot create custom roles; there are no folder or organization hierarchies to configure.","ar":"يجمع منح الوصول عضوًا أو مجموعة، ومشروعًا أو عدة مشاريع للعميل نفسه، ودورًا ثابتًا أو عدة أدوار، ونطاق Production أو Staging أو Development أو كل البيئات. تتكامل الأدوار داخل نطاقاتها. لا ينشئ العملاء أدوارًا مخصصة، ولا توجد مجلدات أو هياكل مؤسسات يحتاجون إلى ضبطها."}}]},{"id":"separation","title":{"en":"Owner versus teammate","ar":"المالك وعضو الفريق"},"blocks":[{"type":"paragraph","text":{"en":"The customer owner retains project control and billing. Teammates receive explicit project permissions; no project role gives access to the owner’s invoices, wallet, purchases, or unrestricted Database Manager. A teammate can own independent projects after completing account setup, while shared projects remain governed by their assigned roles. Permissions in VELTNEX do not create Odoo application users or replace Odoo access rights.","ar":"يحتفظ مالك حساب العميل بالتحكم في المشروع والفوترة. يحصل أعضاء الفريق على صلاحيات صريحة للمشاريع؛ ولا يمنح أي دور فواتير المالك أو محفظته أو الشراء أو مدير قواعد البيانات غير المقيّد. يستطيع عضو الفريق امتلاك مشاريع مستقلة بعد اكتمال إعداد حسابه، وتظل المشاريع المشتركة خاضعة لأدواره. صلاحيات VELTNEX لا تنشئ مستخدمي تطبيق Odoo ولا تستبدل صلاحياته."}}]},{"id":"example","title":{"en":"Example","ar":"مثال"},"blocks":[{"type":"paragraph","text":{"en":"For a release teammate, assign Project Viewer + Logs Viewer + Deployment Operator to selected projects in Staging and Development. This enables inspecting and deploying those environments without deploying Production, accessing Shell, deleting databases, or managing billing.","ar":"لعضو يتابع الإصدارات، امنح قارئ المشروع وقارئ السجلات ومسؤول Deployment على المشاريع المطلوبة في Staging وDevelopment. يستطيع مراجعة هذه البيئات ونشرها دون النشر إلى Production أو فتح Shell أو حذف القواعد أو إدارة الفوترة."}}]}],"related":["iam-roles","iam-scopes","iam-grants"],"sources":["control-plane/saas_iam/roles.py","control-plane/saas_iam/models/iam.py"]},{"id":"iam-roles","title":{"en":"Fixed role reference","ar":"مرجع الأدوار الثابتة"},"summary":{"en":"Compare all predefined roles and combinations.","ar":"قارن جميع الأدوار المحددة مسبقًا وطريقة جمعها."},"kind":"reference","reviewed":"2026-10-05","sections":[{"id":"catalog","title":{"en":"Role catalog","ar":"دليل الأدوار"},"blocks":[{"type":"paragraph","text":{"en":"Every fixed role includes basic project and environment viewing within its scope. Additional actions are listed below. Role codes and permission identifiers are technical identifiers; the displayed role labels are localized.","ar":"يشمل كل دور ثابت عرض المشروع والبيئة الأساسي داخل نطاقه. يعرض الجدول الإجراءات الإضافية. رموز الأدوار ومعرّفات الصلاحيات قيم تقنية، بينما تُعرّب التسميات الظاهرة."}},{"type":"table","headers":[{"en":"Role","ar":"الدور"},{"en":"Additional access","ar":"الوصول الإضافي"}],"rows":[[{"en":"Project Viewer","ar":"قارئ المشروع"},{"en":"View project details, metrics, and build metadata; no log output.","ar":"عرض تفاصيل المشروع والمقاييس وبيانات البناء دون مخرجات السجلات."}],[{"en":"Logs Viewer","ar":"قارئ السجلات"},{"en":"Read application logs and deployment output.","ar":"قراءة سجلات التطبيق ومخرجات Deployment."}],[{"en":"Deployment Operator","ar":"مسؤول Deployment"},{"en":"Deploy existing code configuration and upgrade named database modules; view build metadata and database list.","ar":"تنفيذ Deployment للإعداد الموجود وتحديث وحدات القاعدة المحددة، وعرض بيانات البناء وقائمة القواعد."}],[{"en":"Instance Operator","ar":"مسؤول تشغيل Instance"},{"en":"Start, stop, and restart the environment.","ar":"بدء تشغيل البيئة وإيقافها وإعادة تشغيلها."}],[{"en":"Environment Creator","ar":"مسؤول إنشاء البيئات"},{"en":"Create Staging/Development servers within reserved capacity.","ar":"إنشاء خوادم Staging وDevelopment ضمن السعة المحجوزة."}],[{"en":"Environment Deleter","ar":"مسؤول حذف البيئات"},{"en":"Delete Staging/Development servers, optionally their Git branch.","ar":"حذف خوادم Staging وDevelopment وفرع Git اختياريًا."}],[{"en":"Database Creator","ar":"مسؤول إنشاء قواعد البيانات"},{"en":"List and create databases. Duplication also needs backup download.","ar":"عرض القواعد وإنشاؤها. تتطلب النسخة المطابقة أيضًا تنزيل النسخ."}],[{"en":"Database Backup Operator","ar":"مسؤول النسخ الاحتياطي لقواعد البيانات"},{"en":"List databases/backups and create backups.","ar":"عرض القواعد والنسخ وإنشاء نسخ احتياطية."}],[{"en":"Database Backup Downloader","ar":"مسؤول تنزيل النسخ الاحتياطية"},{"en":"List databases/backups and download completed backups.","ar":"عرض القواعد والنسخ وتنزيل النسخ المكتملة."}],[{"en":"Database Restore Operator","ar":"مسؤول استعادة قواعد البيانات"},{"en":"List databases/backups and restore databases or snapshots.","ar":"عرض القواعد والنسخ واستعادة القواعد أو اللقطات."}],[{"en":"Database Deleter","ar":"مسؤول حذف قواعد البيانات"},{"en":"List and permanently delete databases.","ar":"عرض القواعد وحذفها نهائيًا."}],[{"en":"Database Access Administrator","ar":"مسؤول وصول قواعد البيانات"},{"en":"List databases and reset database administrator passwords.","ar":"عرض القواعد وإعادة تعيين كلمات مرور مسؤوليها."}],[{"en":"SQL Operator","ar":"مسؤول SQL"},{"en":"List databases and run the read-only SQL console.","ar":"عرض القواعد وتشغيل أداة SQL للقراءة فقط."}],[{"en":"Terminal Operator","ar":"مسؤول Terminal"},{"en":"Open the instance Shell.","ar":"فتح Shell الخاصة بـ Instance."}],[{"en":"Project Access Administrator","ar":"مسؤول صلاحيات المشروع"},{"en":"Manage access within their own permissions and environment scopes.","ar":"إدارة الوصول ضمن صلاحياته ونطاقات البيئات الممنوحة له."}],[{"en":"Project Administrator","ar":"مدير المشروع"},{"en":"All project permissions, including configuration and destructive actions, but not owner billing or unrestricted Database Manager.","ar":"كل صلاحيات المشروع بما فيها الضبط والإجراءات التي تحذف البيانات، دون فوترة المالك أو مدير قواعد البيانات غير المقيّد."}]]}]},{"id":"combine","title":{"en":"Combine roles deliberately","ar":"جمع الأدوار بعناية"},"blocks":[{"type":"paragraph","text":{"en":"Backup creation and download are separate permissions. Duplication needs Database Creator + Database Backup Downloader. Copying across environments needs backup download on the source and database restore on the target. A Logs Viewer does not gain deployment permission, and a Project Viewer does not gain log output. Reserve Project Administrator for people who need all project actions.","ar":"إنشاء النسخة وتنزيلها صلاحيتان منفصلتان. تتطلب النسخة المطابقة مسؤول إنشاء قواعد البيانات ومسؤول تنزيل النسخ. يحتاج النسخ بين البيئات تنزيل النسخ في المصدر والاستعادة في الهدف. قارئ السجلات لا يحصل على Deployment، وقارئ المشروع لا يحصل على مخرجات السجلات. امنح مدير المشروع فقط لمن يحتاج جميع إجراءات المشروع."}}]}],"related":["iam-grants","iam-scopes","database-access"],"sources":["control-plane/saas_iam/roles.py","control-plane/saas_iam/models/integration.py"]},{"id":"iam-scopes","title":{"en":"Choose project and environment scopes","ar":"اختيار نطاقات المشاريع والبيئات"},"summary":{"en":"Grant access to exactly the projects and environment types needed.","ar":"امنح الوصول إلى المشاريع وأنواع البيئات المطلوبة فقط."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"scope","title":{"en":"How scopes apply","ar":"تطبيق النطاقات"},"blocks":[{"type":"paragraph","text":{"en":"Select one or multiple customer projects and the environment types covered. **All environments** includes Production, Staging, and Development. A Production-only role cannot operate Staging, and a Staging-only role cannot operate Production. New environments of an authorized type in the assigned project fall within that type’s scope.","ar":"اختر مشروعًا أو عدة مشاريع للعميل وأنواع البيئات التي يشملها الوصول. **كل البيئات** تشمل Production وStaging وDevelopment. دور Production وحده لا يتيح تشغيل Staging، ودور Staging لا يتيح Production. تدخل البيئات الجديدة من النوع المصرّح به داخل المشروع المحدد ضمن نطاق هذا النوع."}}]},{"id":"empty","title":{"en":"An empty scope is still meaningful","ar":"النطاق الفارغ له معنى"},"blocks":[{"type":"paragraph","text":{"en":"You can grant Staging access before the owner creates Staging. The teammate can discover the project but sees no authorized environments until one exists. Do not add Production solely to make the page look populated. Choose Production only when live-environment access is intended.","ar":"يمكن منح وصول Staging قبل إنشاء بيئتها. يستطيع العضو العثور على المشروع، لكنه لا يرى بيئات مصرحًا بها حتى توجد بيئة من هذا النوع. لا تضف Production لمجرد إظهار محتوى في الصفحة؛ اخترها عندما تقصد منح الوصول إلى البيئة الفعلية."}}]},{"id":"limits","title":{"en":"Delegation boundaries","ar":"حدود تفويض الوصول"},"blocks":[{"type":"paragraph","text":{"en":"A Project Access Administrator can grant only permissions and environment scopes already available to them. They cannot promote themselves or someone else beyond their own access. Owner-only team-profile, group, capacity, and billing management remains separate.","ar":"لا يمنح مسؤول صلاحيات المشروع إلا صلاحيات ونطاقات يملكها أصلًا. لا يستطيع رفع صلاحياته أو صلاحيات غيره فوق وصوله. تبقى إدارة ملفات الأعضاء والمجموعات والسعة والفوترة الخاصة بالمالك مستقلة."}}]}],"related":["project-workspace","iam-grants","iam-roles"],"sources":["control-plane/saas_iam/models/iam.py","control-plane/saas_iam/controllers/api.py"]},{"id":"iam-grants","title":{"en":"Grant and remove project access","ar":"منح وصول المشروع وإلغاؤه"},"summary":{"en":"Assign fixed roles to people or groups across selected projects.","ar":"عيّن أدوارًا ثابتة لأعضاء أو مجموعات عبر المشاريع المختارة."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"grant","title":{"en":"Grant access","ar":"منح الوصول"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open **Team & permissions**, globally or from the project. Use the customer/project filter to verify the workspace.","ar":"افتح **الفريق والصلاحيات** من التنقل العام أو المشروع، وتحقق من مساحة العمل عبر تصفية العميل والمشروع."},{"en":"Choose **Grant access**, select an existing teammate or team group, and select the projects. Add the teammate first if they are not listed.","ar":"اختر **منح الوصول** وحدّد عضوًا موجودًا أو مجموعة ثم المشاريع. أضف العضو أولًا إذا لم يظهر."},{"en":"Select fixed roles and Production, Staging, Development, or all environments. Review destructive roles before saving.","ar":"حدّد الأدوار الثابتة ونطاق Production أو Staging أو Development أو الكل، وراجع الأدوار التي تتيح الحذف قبل الحفظ."},{"en":"Check the resulting role rows and ask the teammate to complete setup or accept an invitation if required.","ar":"راجع صفوف الأدوار الناتجة واطلب من العضو إكمال إعداد حسابه أو قبول الدعوة عند الحاجة."}]}]},{"id":"revoke","title":{"en":"Remove access","ar":"إلغاء الوصول"},"blocks":[{"type":"paragraph","text":{"en":"Remove the applicable role grants and review group membership too. Effective access is the union of direct and group grants; removing one path does not remove another. Revocation blocks later authorization checks, closes terminals that no longer qualify, and cancels unauthorized queued work. Work already executing can finish. Downloaded data remains outside the platform’s control.","ar":"ألغِ منح الأدوار المعنية وراجع عضوية المجموعات أيضًا. يجمع الوصول الفعلي المنح المباشرة ومنح المجموعات؛ وإلغاء مسار لا يلغي الآخر. يمنع الإلغاء فحوص الصلاحية اللاحقة ويغلق Terminal التي فقدت صلاحيتها ويلغي العمل المنتظر غير المصرّح به. قد يكتمل العمل الجاري، وتبقى البيانات المنزّلة خارج سيطرة المنصة."}}]}],"related":["iam-groups","teammate-profiles","iam-troubleshooting"],"sources":["frontend/veltnex/src/pages/portal/ProjectAccess.tsx","control-plane/saas_iam/models/iam.py","control-plane/saas_iam/models/integration.py"]},{"id":"teammate-profiles","title":{"en":"Add and manage teammates","ar":"إضافة أعضاء الفريق وإدارتهم"},"summary":{"en":"Create a managed login or connect an existing account without taking it over.","ar":"أنشئ حسابًا مُدارًا أو اربط حسابًا موجودًا دون التحكم ببيانات دخوله."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"create","title":{"en":"Add a teammate","ar":"إضافة عضو"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"As the customer owner, open **Team & permissions → Teammates → Add teammate**.","ar":"بصفتك مالك حساب العميل، افتح **الفريق والصلاحيات ← أعضاء الفريق ← إضافة عضو الفريق**."},{"en":"Enter the name and email. A phone is optional at creation; select the country to apply its dialing code and check the final number.","ar":"أدخل الاسم والبريد. الهاتف اختياري عند الإنشاء؛ اختر الدولة لإضافة مفتاحها وتحقق من الرقم النهائي."},{"en":"Create the profile. A new managed account returns a generated temporary password once. Save or share it before closing the dialog.","ar":"أنشئ الملف. يعرض الحساب المُدار الجديد كلمة مرور مؤقتة مرة واحدة. احفظها أو شاركها قبل إغلاق النافذة."},{"en":"Assign the required roles separately. Creating a profile alone does not grant project actions.","ar":"عيّن الأدوار المطلوبة بشكل مستقل. إنشاء الملف وحده لا يمنح إجراءات المشروع."}]}]},{"id":"existing","title":{"en":"Existing and shared accounts","ar":"الحسابات الموجودة والمشتركة"},"blocks":[{"type":"paragraph","text":{"en":"Existing independent accounts keep their passwords and contact details. Accounts managed by another customer require an accepted invitation before association. The owner cannot reset an independent/shared login, or take over an account with its own projects or billing records. Phone uniqueness checks include normalized numbers and inactive logins.","ar":"تحتفظ الحسابات المستقلة الموجودة بكلمات مرورها وبياناتها. تحتاج الحسابات التي يديرها عميل آخر إلى دعوة مقبولة قبل الربط. لا يعيد المالك تعيين دخول مستقل أو مشترك، ولا يتحكم بحساب له مشاريعه أو سجلات فوترة خاصة به. تشمل فحوص الهاتف الأرقام بعد توحيد صيغتها وحسابات الدخول غير النشطة."}}]},{"id":"delete","title":{"en":"Delete a profile","ar":"حذف ملف عضو"},"blocks":[{"type":"paragraph","text":{"en":"Deleting a teammate profile removes that customer’s direct grants, group membership, and invitations. A verified, independently owned, or shared login stays available to its holder and other projects. An unverified account used exclusively by the team can be disabled. Deleting the profile is not the same as deleting the person’s verified account.","ar":"يحذف ملف العضو المنح المباشرة وعضوية المجموعات والدعوات لهذا العميل. يبقى الدخول الموثّق أو المستقل أو المشترك متاحًا لصاحبه ومشاريعه الأخرى. قد يُعطّل الحساب غير الموثّق المستخدم حصريًا للفريق. حذف ملف العضو لا يعني حذف حسابه الموثّق."}}]}],"related":["teammate-credentials","teammate-onboarding","iam-invitations"],"sources":["control-plane/saas_iam/models/members.py","frontend/veltnex/src/pages/portal/ProjectAccess.tsx"]},{"id":"teammate-credentials","title":{"en":"Share or reset teammate credentials","ar":"مشاركة بيانات دخول عضو أو إعادة تعيينها"},"summary":{"en":"Send temporary credentials by email or download a local file.","ar":"أرسل بيانات الدخول المؤقتة بالبريد أو نزّل ملفًا محليًا."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"share","title":{"en":"Share sign-in details","ar":"مشاركة بيانات الدخول"},"blocks":[{"type":"paragraph","text":{"en":"After creating a new managed login or resetting an eligible password, the credentials dialog offers **Send credentials by email** and **Download credentials**. Email goes to the login address through the platform’s outgoing mail queue. Queued delivery does not guarantee inbox delivery. Download creates a local text file containing the login URL, email, temporary password, and first-login instructions.","ar":"بعد إنشاء دخول مُدار أو إعادة تعيين كلمة مرور مؤهلة، تتيح نافذة البيانات **إرسال بيانات الدخول بالبريد الإلكتروني** و**تنزيل بيانات الدخول**. يصل الطلب إلى بريد الدخول عبر قائمة البريد الصادر للمنصة. إدراجه في قائمة الإرسال لا يضمن وصوله إلى صندوق البريد. يُنشئ التنزيل ملفًا نصيًا محليًا يحتوي رابط الدخول والبريد وكلمة المرور المؤقتة وخطوات الدخول الأول."}},{"type":"note","tone":"warning","text":{"en":"The temporary password is shown once. Store the file privately and share it through an appropriate channel. The platform does not keep it in browser storage; closing the dialog can require a reset to obtain new credentials.","ar":"تظهر كلمة المرور المؤقتة مرة واحدة. احفظ الملف بصورة خاصة وشاركه بقناة مناسبة. لا تخزّن المنصة الكلمة في تخزين المتصفح؛ وقد تحتاج إعادة تعيينها للحصول على بيانات جديدة بعد إغلاق النافذة."}}]},{"id":"reset","title":{"en":"Reset an eligible teammate password","ar":"إعادة تعيين كلمة مرور عضو مؤهل"},"blocks":[{"type":"paragraph","text":{"en":"The owner can reset a login created and managed exclusively for their team, subject to current ownership checks. A reset issues a new temporary password, invalidates sessions and pending authorized work, and requires password replacement and phone verification again. Existing independent accounts, accounts shared across customers, and accounts with their own projects/billing manage their own passwords.","ar":"يستطيع المالك إعادة تعيين دخول أُنشئ ويُدار حصريًا لفريقه وفق فحوص الملكية الحالية. ينتج عن الإعادة كلمة مؤقتة جديدة وإبطال الجلسات والعمل المنتظر المرتبط بالصلاحية، واشتراط تغيير الكلمة والتحقق من الهاتف مرة أخرى. تدير الحسابات المستقلة أو المشتركة بين العملاء أو التي تملك مشاريع وفوترة كلمات مرورها بنفسها."}}]}],"related":["teammate-profiles","teammate-onboarding","password-recovery"],"sources":["control-plane/saas_iam/models/members.py","frontend/veltnex/src/pages/portal/ProjectAccess.tsx"]},{"id":"teammate-onboarding","title":{"en":"Complete your first teammate login","ar":"إكمال الدخول الأول لعضو الفريق"},"summary":{"en":"Replace the temporary password, then verify or change your mobile number.","ar":"استبدل كلمة المرور المؤقتة ثم تحقّق من رقمك أو غيّره وتحقّق منه."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"steps","title":{"en":"Required setup","ar":"الإعداد المطلوب"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Sign in using the email and temporary password supplied by the owner.","ar":"سجّل بالبريد وكلمة المرور المؤقتة التي أعطاك إياها المالك."},{"en":"Choose your own password: at least 12 characters and different from the temporary password.","ar":"اختر كلمة مرور خاصة بك من 12 حرفًا على الأقل ومختلفة عن الكلمة المؤقتة."},{"en":"Confirm the supplied phone or enter your own number with the correct country code. The number must not belong to another login.","ar":"أكّد الهاتف المسجّل أو أدخل رقمك بمفتاح الدولة الصحيح، ويجب ألا يخص الرقم حساب دخول آخر."},{"en":"Request the WhatsApp code, enter the newest code, and complete verification before opening projects.","ar":"اطلب رمز WhatsApp وأدخل الرمز الأخير وأكمل التحقق قبل فتح المشاريع."}]}]},{"id":"enforcement","title":{"en":"Setup is required on every route","ar":"الإعداد مطلوب قبل الوصول"},"blocks":[{"type":"paragraph","text":{"en":"Refreshing, opening a shared project URL, or changing browser tabs does not bypass setup. Project and workspace actions remain blocked until both steps finish. Teammate codes expire after 10 minutes and allow 5 incorrect guesses; resending replaces the old challenge. Delivery and verification are also rate limited.","ar":"لا يتجاوز تحديث الصفحة أو فتح رابط مشروع مشترك أو تبديل التبويبات الإعداد. تبقى إجراءات المشروع ومساحة العمل محظورة حتى اكتمال الخطوتين. ينتهي رمز العضو بعد 10 دقائق ويسمح بـ 5 محاولات خاطئة؛ ويستبدل طلب رمز جديد الرمز السابق. توجد كذلك حدود لمعدل الإرسال والتحقق."}}]},{"id":"test","title":{"en":"Testing and unavailable WhatsApp","ar":"الاختبار وتعذّر WhatsApp"},"blocks":[{"type":"paragraph","text":{"en":"If the platform explicitly enables testing and WhatsApp is unconfigured, the setup screen can show a test code. You must still enter it; it is not a skip button. This is not normal production phone verification. Once real WhatsApp is configured or testing is disabled, test codes stop being accepted and test-verified teammates may need real verification. If no code or delivery method is available, contact support.","ar":"إذا فعّلت المنصة الاختبار صراحة ولم يُضبط WhatsApp، فقد تعرض الصفحة رمزًا تجريبيًا. يجب إدخاله؛ فهو ليس زر تجاوز. لا يمثل ذلك التحقق الفعلي المعتاد. عند إعداد WhatsApp أو تعطيل الاختبار لا تُقبل الرموز التجريبية، وقد يحتاج الأعضاء الذين تحقّقوا بها إلى تحقق فعلي. إذا لم يتوفر رمز أو إرسال فتواصل مع الدعم."}}]}],"related":["teammate-credentials","iam-troubleshooting"],"sources":["control-plane/saas_iam/models/members.py","control-plane/saas_iam/models/whatsapp.py","frontend/veltnex/src/pages/portal/PasswordSetup.tsx"]},{"id":"iam-groups","title":{"en":"Manage team groups","ar":"إدارة مجموعات الفريق"},"summary":{"en":"Assign access to a group and maintain its membership.","ar":"امنح الوصول لمجموعة وأدر عضويتها."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"steps","title":{"en":"Create and use a group","ar":"إنشاء مجموعة واستخدامها"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"As the owner, open the Groups tab in Team & permissions and create a named group.","ar":"بصفتك المالك، افتح تبويب المجموعات في الفريق والصلاحيات وأنشئ مجموعة باسم واضح."},{"en":"Add established teammates as members. Profiles or accepted invitations make users available to the team.","ar":"أضف أعضاء الفريق المرتبطين بالحساب. تتيح ملفات الأعضاء أو الدعوات المقبولة اختيارهم للفريق."},{"en":"Grant the group fixed roles on selected projects and environments, just as you would for an individual.","ar":"امنح المجموعة أدوارًا ثابتة على المشاريع والبيئات المحددة كما تفعل للعضو الفردي."},{"en":"Review membership regularly. Removing a member removes group-derived access, but their direct roles or membership in another group can still authorize actions.","ar":"راجع العضوية دوريًا. إزالة عضو تلغي وصول المجموعة، لكن أدواره المباشرة أو عضويته في مجموعة أخرى قد تظل تمنحه صلاحيات."}]}]},{"id":"ownership","title":{"en":"Management and deletion","ar":"الإدارة والحذف"},"blocks":[{"type":"paragraph","text":{"en":"Only the customer owner manages group membership. Project Access Administrators can grant project roles to eligible groups within their delegation limits; they cannot manage the customer’s whole team. Deleting a group deactivates it and revokes its effective group access without deleting member logins.","ar":"يدير مالك حساب العميل وحده عضوية المجموعات. يستطيع مسؤول صلاحيات المشروع منح أدوار للمجموعات المؤهلة ضمن حدود تفويضه، لكنه لا يدير فريق العميل بالكامل. يعطّل حذف المجموعة وصولها دون حذف حسابات أعضائها."}}]}],"related":["iam-grants","iam-roles","teammate-profiles"],"sources":["control-plane/saas_iam/models/iam.py","control-plane/saas_iam/controllers/api.py"]},{"id":"iam-invitations","title":{"en":"Invite an existing account","ar":"دعوة حساب موجود"},"summary":{"en":"Use an email-bound invitation to establish access safely.","ar":"استخدم دعوة مرتبطة بالبريد لربط الحساب ومنحه الوصول بأمان."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"invite","title":{"en":"Create and accept an invitation","ar":"إنشاء الدعوة وقبولها"},"blocks":[{"type":"paragraph","text":{"en":"Where the access workflow requires an invitation, select the email, projects, roles, and environment scopes. The invitation can be sent using configured outgoing mail or shared as a copied link. The recipient signs in with an active account whose login matches the invited email, then accepts. Pending invitations do not provide accepted project access.","ar":"عندما يتطلب مسار الوصول دعوة، حدّد البريد والمشاريع والأدوار ونطاقات البيئات. يمكن إرسالها بالبريد الصادر المُعدّ أو مشاركة رابطها المنسوخ. يسجّل المستلم بحساب نشط يطابق بريد دخوله البريد المدعو ثم يقبل الدعوة. الدعوة المعلّقة لا تمنح وصولًا مقبولًا للمشروع."}}]},{"id":"expiry","title":{"en":"Expiry and cancellation","ar":"انتهاء الدعوة وإلغاؤها"},"blocks":[{"type":"paragraph","text":{"en":"Invitations expire after 7 days. A wrong signed-in account cannot accept them. Removing all pending grants invalidates the invitation’s access. If acceptance fails, check the login email, expiry, and whether access is still pending; ask the owner or access administrator for a new invitation if necessary. An invitation does not transfer ownership of an existing account’s password.","ar":"تنتهي الدعوة بعد 7 أيام، ولا يقبلها حساب دخول مختلف. إلغاء جميع المنح المعلّقة يبطل الوصول المرتبط بالدعوة. إذا تعذّر القبول، راجع بريد الدخول والانتهاء واستمرار المنح، واطلب دعوة جديدة من المالك أو مسؤول الصلاحيات عند الحاجة. لا تنقل الدعوة التحكم بكلمة مرور حساب موجود."}}]}],"related":["teammate-profiles","iam-grants","iam-troubleshooting"],"sources":["control-plane/saas_iam/models/iam.py","frontend/veltnex/src/pages/portal/AcceptAccess.tsx"]}]},{"id":"observability","title":{"en":"Monitoring and developer tools","ar":"المراقبة وأدوات التطوير"},"description":{"en":"Inspect metrics and logs, query data safely, and use the browser Shell.","ar":"راجع المقاييس والسجلات واستعلم عن البيانات واستخدم Shell من المتصفح."},"articles":[{"id":"monitoring","title":{"en":"Monitor resource usage","ar":"مراقبة استخدام الموارد"},"summary":{"en":"Read live metrics and performance history without treating missing data as zero load.","ar":"اقرأ المقاييس المباشرة والسجل دون تفسير غياب البيانات باعتباره استخدامًا صفريًا."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"metrics","title":{"en":"Metrics and ranges","ar":"المقاييس والفترات"},"blocks":[{"type":"paragraph","text":{"en":"Project viewing access includes CPU, RAM, and storage information. Live metrics distinguish Odoo and database resource shares where available. The Metrics tab provides 1h, 6h, 24h, 7d, and 14d windows. Values are relative to the resource package and can be sampled or cached; they are not per-user performance measurements.","ar":"يشمل عرض المشروع معلومات CPU وRAM والتخزين. تميّز المقاييس المباشرة بين حصة Odoo وحصة قاعدة البيانات عند توفرها. يعرض تبويب المقاييس فترات 1h و6h و24h و7d و14d. تُقاس القيم بالنسبة إلى الموارد المخصصة وقد تكون عينات أو قياسات مخزّنة مؤقتًا؛ وليست قياسًا لأداء كل مستخدم."}}]},{"id":"interpret","title":{"en":"Interpret the charts","ar":"قراءة المخططات"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Choose the environment and a range that includes the reported slow period.","ar":"اختر البيئة والفترة التي تشمل وقت البطء المبلّغ عنه."},{"en":"Compare sustained pressure with deployments, scheduled jobs, imports, and busy business hours.","ar":"قارن الضغط المستمر مع Deployment والمهام المجدولة والاستيراد وأوقات ازدحام العمل."},{"en":"Treat unavailable metrics or gaps as missing observations, not proof that the instance was healthy or idle.","ar":"اعتبر المقاييس غير المتاحة والفجوات بيانات مفقودة، لا دليلًا على سلامة Instance أو خمولها."},{"en":"Use logs and read-only SQL to investigate expensive application behavior before deciding whether to scale.","ar":"استخدم السجلات وSQL للقراءة فقط لفهم السلوك المكلف قبل اتخاذ قرار زيادة الموارد."}]}]}],"related":["sizing","application-logs","sql-console","storage-capacity"],"sources":["frontend/veltnex/src/components/PerformanceHistory.tsx","control-plane/saas_core/models/saas_instance.py"]},{"id":"application-logs","title":{"en":"View and download application logs","ar":"عرض سجلات التطبيق وتنزيلها"},"summary":{"en":"Stream current runtime output and preserve useful evidence.","ar":"تابع مخرجات التشغيل واحفظ المعلومات المفيدة للتشخيص."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"use","title":{"en":"Use the Logs tab","ar":"استخدام تبويب السجلات"},"blocks":[{"type":"paragraph","text":{"en":"Logs are a hosting-only feature and require a running environment and **Logs Viewer**. Open Logs for the selected environment. Severity colors distinguish errors, warnings, debug output, and normal messages. Use Pause/Resume, auto-scroll, clear, and download controls to inspect the visible output. Clear affects the browser view, not a permanent server-log deletion request.","ar":"السجلات خاصية للاستضافة وتتطلب بيئة تعمل ودور **قارئ السجلات**. افتح السجلات للبيئة المختارة. تميّز الألوان الأخطاء والتنبيهات ورسائل Debug والرسائل العادية. استخدم الإيقاف المؤقت والاستئناف والتمرير التلقائي والمسح والتنزيل لمراجعة المخرجات. المسح يزيل عرض المتصفح ولا يطلب حذف سجلات الخادم الدائمة."}}]},{"id":"limits","title":{"en":"Streaming limits and language","ar":"حدود البث واللغة"},"blocks":[{"type":"paragraph","text":{"en":"The page keeps a bounded recent browser buffer rather than an unlimited log archive. Download preserves the currently collected output, not every historical log. Streams can end because the environment stopped, permissions changed, the connection broke, or a stream timeout occurred. Resume to reconnect after resolving the cause. Technical logs remain left-to-right in Arabic, and their contents and timestamps are not translated.","ar":"تحتفظ الصفحة بعدد محدود من الرسائل الحديثة في المتصفح، وليست أرشيفًا غير محدود. يحفظ التنزيل المخرجات التي جمعتها الصفحة، لا كل السجلات السابقة. قد ينتهي البث بسبب توقف البيئة أو تغيّر الصلاحيات أو انقطاع الاتصال أو انتهاء مدة البث. استأنفه بعد معالجة السبب. تبقى السجلات التقنية من اليسار إلى اليمين في العربية دون ترجمة محتوياتها أو توقيتها."}}]},{"id":"share","title":{"en":"Share useful evidence","ar":"إرسال معلومات مفيدة"},"blocks":[{"type":"paragraph","text":{"en":"Include the environment name, exact error, relevant surrounding lines, and event time when contacting support. Remove access tokens, passwords, and unnecessary customer data. Deployment output is a separate history view and also requires Logs Viewer.","ar":"أرسل اسم البيئة والخطأ كما ظهر والأسطر المحيطة به ووقت الحدث عند التواصل مع الدعم. أزل Tokens وكلمات المرور وبيانات العملاء غير اللازمة. مخرجات Deployment موجودة في سجل مستقل وتتطلب كذلك قارئ السجلات."}}]}],"related":["deployment-history","deployment-troubleshooting"],"sources":["frontend/veltnex/src/pages/portal/Logs.tsx","control-plane/saas_core/controllers/container_logs.py"]},{"id":"sql-console","title":{"en":"Run read-only SQL queries","ar":"تشغيل استعلامات SQL للقراءة فقط"},"summary":{"en":"Explore a database without using the console for write operations.","ar":"استكشف قاعدة البيانات دون استخدام الأداة لتعديلها."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Requirements and limits","ar":"المتطلبات والحدود"},"blocks":[{"type":"paragraph","text":{"en":"Use a running hosting environment and **SQL Operator**. Select a database from the environment’s list. Queries run in a PostgreSQL read-only transaction and are rolled back when complete. Writes and schema changes are rejected; this is not an administrator mutation tool. Results default to 1000 rows; the backend caps a requested limit at 10000.","ar":"استخدم بيئة استضافة تعمل ودور **مسؤول SQL**، واختر قاعدة من قائمة البيئة. تعمل الاستعلامات داخل معاملة PostgreSQL للقراءة فقط ويُتراجع عنها عند الانتهاء. تُرفض الكتابة وتغييرات البنية؛ فلا تستخدم الأداة لتعديل القاعدة. الافتراضي 1000 صف، ويحد Backend الحد المطلوب عند 10000."}}]},{"id":"query","title":{"en":"Run and interpret a query","ar":"تشغيل الاستعلام وقراءة النتيجة"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Open SQL, select the database, and enter a query using the database’s actual table and field names.","ar":"افتح SQL واختر القاعدة واكتب الاستعلام بأسماء الجداول والحقول الفعلية."},{"en":"Select Run or press Ctrl/⌘ + Enter.","ar":"اختر التشغيل أو اضغط Ctrl/⌘ + Enter."},{"en":"Review columns, rows, null values, and the truncated indicator. Add a smaller LIMIT or filtering condition when appropriate.","ar":"راجع الأعمدة والصفوف وقيم null ومؤشر اقتطاع النتائج. أضف LIMIT أصغر أو شرط تصفية عند الحاجة."}]},{"type":"code","language":"sql","code":"SELECT id, name\\nFROM res_partner\\nORDER BY id\\nLIMIT 20;"}]},{"id":"errors","title":{"en":"Query errors","ar":"أخطاء الاستعلام"},"blocks":[{"type":"paragraph","text":{"en":"SQL syntax and permission errors are shown so you can correct the query. Read-only access can still expose sensitive records within the selected database; grant this role only to trusted users. Avoid expensive unbounded queries on Production.","ar":"تعرض الأداة أخطاء صياغة SQL والصلاحيات لتصحيح الاستعلام. قد تكشف القراءة بيانات حساسة داخل القاعدة المختارة؛ لذا امنح الدور للمستخدمين الموثوقين فقط. تجنّب الاستعلامات المكلفة غير المحدودة في Production."}}]}],"related":["iam-roles","monitoring","shell-console"],"sources":["control-plane/saas_core/models/saas_instance.py","frontend/veltnex/src/pages/portal/SqlConsole.tsx"]},{"id":"shell-console","title":{"en":"Use the browser Shell","ar":"استخدام Shell من المتصفح"},"summary":{"en":"Open a scoped terminal and understand session and persistence limits.","ar":"افتح Terminal محددة النطاق وافهم حدود الجلسة واستمرار التغييرات."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"before","title":{"en":"Access and boundary","ar":"الوصول وحدوده"},"blocks":[{"type":"paragraph","text":{"en":"Shell is a hosting-only tool requiring a running environment and **Terminal Operator**. The customer terminal opens the instance’s dedicated Shell Container, not the Kubernetes host or a platform administrator terminal. It does not expose the application’s master/database credentials.","ar":"Shell أداة للاستضافة وتتطلب بيئة تعمل ودور **مسؤول Terminal**. تفتح Terminal العميل الـ Container المخصصة لـ Shell داخل Instance، وليس مضيف Kubernetes أو Terminal مسؤول المنصة. لا تكشف بيانات القاعدة أو كلمة المرور الرئيسية للتطبيق."}}]},{"id":"steps","title":{"en":"Open and close a session","ar":"فتح الجلسة وإغلاقها"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Select the correct environment and open Shell. Wait if the access Container is still being prepared.","ar":"اختر البيئة الصحيحة وافتح Shell، وانتظر إذا كانت Container الوصول لا تزال قيد التجهيز."},{"en":"Run diagnostic commands supported by the available tools and your environment. Do not assume root access or application database credentials.","ar":"شغّل أوامر التشخيص التي تدعمها الأدوات والبيئة. لا تفترض وصول root أو توفر اعتمادات قاعدة التطبيق."},{"en":"Close the terminal when finished. Reconnect if the session expires or the instance is redeployed.","ar":"أغلق Terminal عند الانتهاء، وأعد الاتصال إذا انتهت الجلسة أو أُعيد Deployment للبيئة."}]}]},{"id":"limits","title":{"en":"Session and persistence","ar":"الجلسة واستمرار التغييرات"},"blocks":[{"type":"paragraph","text":{"en":"Idle terminals are cleaned up after approximately 10 minutes. Replaced runtime Containers do not preserve arbitrary local edits or package installations. Keep permanent application code and Python dependencies in Git and the build configuration. Treat commands as real actions in the scoped environment, and avoid sharing terminal output that contains private data.","ar":"تُنظّف جلسات Terminal الخاملة بعد نحو 10 دقائق. لا تحفظ Containers التي تُستبدل أي تعديل محلي أو حزمة مثبّتة تلقائيًا. ضع الكود الدائم ومتطلبات Python في Git وإعداد البناء. تعامل مع الأوامر كإجراءات فعلية داخل البيئة المحددة، ولا تشارك مخرجات تحتوي بيانات خاصة."}}]}],"related":["python-dependencies","iam-roles","application-logs"],"sources":["control-plane/saas_core/controllers/ssh_terminal.py","frontend/veltnex/src/pages/portal/ShellConsole.tsx"]}]},{"id":"billing","title":{"en":"Billing and payments","ar":"الفوترة والمدفوعات"},"description":{"en":"Understand invoices, renewal, account credit, optional charges, and support plans.","ar":"افهم الفواتير والتجديد ورصيد الحساب والرسوم الاختيارية وخطط الدعم."},"articles":[{"id":"billing-options","title":{"en":"Monthly and yearly billing","ar":"الفوترة الشهرية والسنوية"},"summary":{"en":"Review subscription cycles and separately billed add-ons.","ar":"راجع دورات الاشتراك والإضافات التي تُفوتر بشكل مستقل."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"cycles","title":{"en":"Billing periods","ar":"دورات الفوترة"},"blocks":[{"type":"paragraph","text":{"en":"Monthly billing charges one cycle at a time. Yearly billing is paid upfront for the annual cycle; any saving is displayed in the configurator and can vary with the active catalog. The checkout total is the authoritative quote, including applicable add-ons and invoice treatment. Changing between periods uses the plan-change workflow.","ar":"تُحاسب الفوترة الشهرية على دورة واحدة في كل مرة، بينما تُدفع الدورة السنوية مقدمًا. يظهر التوفير، إن وجد، في صفحة الإعداد وقد يختلف حسب الكتالوج الفعّال. إجمالي الدفع هو التسعير المعتمد بما يشمل الإضافات ومعالجة الفاتورة. يُغيّر نوع الدورة عبر مسار تغيير الخطة."}}]},{"id":"addons","title":{"en":"Different renewal schedules","ar":"اختلاف مواعيد التجديد"},"blocks":[{"type":"paragraph","text":{"en":"Environment slots and other recurring resources are associated with the Production subscription. Daily backups have a monthly renewal even if the main subscription is yearly, and their price follows measured data. Review each due date and auto-renew setting rather than assuming every charge happens on the same date. Stopping the application does not cancel these charges.","ar":"ترتبط سعة البيئات والموارد المتكررة باشتراك Production. تتجدد النسخ اليومية شهريًا حتى لو كان الاشتراك الرئيسي سنويًا، وتتبع تكلفتها البيانات المقاسة. راجع كل تاريخ استحقاق وإعداد تجديد تلقائي بدل افتراض أن كل الرسوم تُستحق في يوم واحد. إيقاف التطبيق لا يلغي هذه الرسوم."}}]}],"related":["invoices","auto-renew","change-plan"],"sources":["control-plane/saas_billing/models/saas_instance.py","control-plane/saas_billing/models/saas_pricing.py"]},{"id":"invoices","title":{"en":"View and pay invoices","ar":"عرض الفواتير وسدادها"},"summary":{"en":"Read invoice state, line items, balance, and payment results.","ar":"اقرأ حالة الفاتورة وبنودها ورصيدها ونتيجة الدفع."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"view","title":{"en":"Find an invoice","ar":"الوصول إلى الفاتورة"},"blocks":[{"type":"paragraph","text":{"en":"Open Billing using the customer owner account. Select an invoice to view its items, dates, total, and outstanding amount. Use the payment action or PDF download where available. Teammates’ project roles do not expose the owner’s financial records.","ar":"افتح الفوترة بحساب مالك العميل. اختر فاتورة لعرض البنود والتواريخ والإجمالي والمبلغ المتبقي، واستخدم الدفع أو تنزيل PDF عند إتاحتهما. أدوار المشاريع للأعضاء لا تكشف سجلات المالك المالية."}},{"type":"table","headers":[{"en":"Label","ar":"الحالة"},{"en":"Meaning","ar":"المعنى"}],"rows":[[{"en":"Open","ar":"Open"},{"en":"Issued and awaiting settlement.","ar":"صادرة وتنتظر التسوية."}],[{"en":"Overdue","ar":"Overdue"},{"en":"Unpaid beyond the displayed due date.","ar":"غير مدفوعة بعد تاريخ الاستحقاق المعروض."}],[{"en":"Partially paid","ar":"Partially paid"},{"en":"A remaining balance still needs settlement.","ar":"تحتاج تسوية المبلغ المتبقي."}],[{"en":"Paid","ar":"Paid"},{"en":"Payment has been recorded and the invoice is settled.","ar":"سُجّل الدفع وسُوّيت الفاتورة."}]]}]},{"id":"payment","title":{"en":"Complete payment","ar":"إكمال الدفع"},"blocks":[{"type":"paragraph","text":{"en":"Use the available payment provider and return to the invoice or instance page. A provider success screen is not the same as completed platform reconciliation; verify the invoice is Paid and the requested activation is applied. If the provider charged you but the invoice remains open, do not repeatedly pay. Contact support with the invoice and provider transaction reference. Never send full card details.","ar":"استخدم مزوّد الدفع المتاح ثم ارجع إلى صفحة الفاتورة أو Instance. نجاح الدفع لدى المزوّد لا يعني اكتمال تسويته داخل المنصة؛ تحقق من ظهور الدفع وتطبيق التفعيل المطلوب. إذا خُصم المبلغ وبقيت الفاتورة مفتوحة، لا تكرر الدفع. أرسل للدعم الفاتورة ومعرّف عملية المزوّد دون بيانات البطاقة الكاملة."}}]}],"related":["optional-charges","auto-renew","wallet"],"sources":["frontend/veltnex/src/pages/portal/Invoices.tsx","frontend/veltnex/src/pages/portal/InvoiceDetail.tsx","control-plane/saas_billing/models/account_move.py"]},{"id":"optional-charges","title":{"en":"Decline optional charges and understand proration","ar":"رفض الرسوم الاختيارية وفهم التسعير النسبي"},"summary":{"en":"Cancel an optional purchase without confusing it with a renewal obligation.","ar":"ألغِ شراءً اختياريًا دون الخلط بينه وبين فاتورة التجديد."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"decline","title":{"en":"Optional invoices","ar":"الفواتير الاختيارية"},"blocks":[{"type":"paragraph","text":{"en":"A Decline or cancel-charge action appears only for eligible unpaid optional invoices, such as a requested upgrade or capacity/add-on purchase. It cancels that request and handles linked reserved credit. It is not a way to decline an active subscription renewal or undo an already applied paid change.","ar":"يظهر رفض الرسوم أو إلغاؤها للفواتير الاختيارية غير المدفوعة المؤهلة فقط، مثل طلب ترقية أو شراء سعة أو إضافة. يلغي الإجراء الطلب ويعالج الرصيد المحجوز المرتبط به. لا يُستخدم لرفض تجديد اشتراك فعّال أو عكس تغيير مدفوع طُبّق بالفعل."}}]},{"id":"proration","title":{"en":"Unused time and credit","ar":"الوقت غير المستخدم والرصيد"},"blocks":[{"type":"paragraph","text":{"en":"Mid-cycle purchases can be prorated to the renewal date. Plan upgrades account for unused prepaid value through the quote, invoices, and wallet. Releasing unused environment slots can credit their remaining cycle value to the wallet. Deleting the server alone keeps its slot reserved. Review the actual charge and credit shown before confirming.","ar":"قد تُحسب مشتريات منتصف الدورة حسب المدة المتبقية إلى التجديد. تراعي ترقية الخطة القيمة المدفوعة للوقت غير المستخدم عبر التسعير والفواتير والمحفظة. قد يضيف تحرير الأماكن الشاغرة للبيئات قيمة المدة المتبقية إلى المحفظة. حذف الخادم وحده يُبقي المكان محجوزًا. فئات التشغيل الأقل لا تعيد قيمة الفترة الحالية. راجع الرسوم والرصيد الفعليين قبل التأكيد."}}]}],"related":["change-plan","environment-slots","wallet"],"sources":["control-plane/saas_billing/models/saas_instance.py","control-plane/saas_billing/models/account_move.py"]},{"id":"auto-renew","title":{"en":"Manage payment methods and automatic renewal","ar":"إدارة طرق الدفع والتجديد التلقائي"},"summary":{"en":"Control automatic charges while keeping renewal invoices in view.","ar":"تحكّم بالخصم التلقائي مع متابعة فواتير التجديد."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"methods","title":{"en":"Saved payment methods","ar":"طرق الدفع المحفوظة"},"blocks":[{"type":"paragraph","text":{"en":"Saved payment methods depend on the provider’s tokenization and the payment flow. The Settings page lists available methods and the default method. Removing a method disables its use for later automatic charges; it does not cancel an invoice or subscription. Check the provider’s saving option during checkout rather than assuming every payment saves a card.","ar":"يعتمد حفظ طرق الدفع على Tokenization لدى المزوّد ومسار الدفع. تعرض الإعدادات الطرق المتاحة والطريقة الافتراضية. إزالة طريقة تمنع استخدامها في الخصومات التلقائية اللاحقة، لكنها لا تلغي فاتورة أو اشتراكًا. راجع خيار الحفظ أثناء الدفع بدل افتراض حفظ بطاقة في كل عملية."}}]},{"id":"renew","title":{"en":"Automatic renewal","ar":"التجديد التلقائي"},"blocks":[{"type":"paragraph","text":{"en":"The owner can control automatic renewal separately for the subscription and daily backups where enabled. Turning auto-renew off stops automatic charging, not invoice generation. You must still settle renewal invoices or cancel the service through its cancellation workflow.","ar":"يستطيع المالك ضبط التجديد التلقائي للاشتراك والنسخ اليومية بشكل مستقل عند إتاحته. تعطيل التجديد التلقائي يوقف الخصم التلقائي، وليس إصدار الفواتير. يجب تسوية فواتير التجديد أو إلغاء الخدمة من مسار الإلغاء."}}]},{"id":"failure","title":{"en":"Failed renewal payments","ar":"إخفاق دفع التجديد"},"blocks":[{"type":"paragraph","text":{"en":"The default workflow sends reminders 7 and 1 days before renewal, attempts renewal payment, and retries unpaid charges 1, 3, and 5 days after the due date. Main-subscription suspension uses the platform’s grace policy; daily-backup invoices have a separate pause policy. Exact schedules and delivery depend on configured jobs and mail. Review outstanding invoices and contact support if a restriction remains after payment.","ar":"يرسل المسار الافتراضي تذكيرين قبل التجديد بـ 7 و1 يوم، ويحاول الدفع ثم يعيد محاولات الرسوم غير المدفوعة بعد الاستحقاق بـ 1 و3 و5 أيام. يتبع تعليق الاشتراك الرئيسي سياسة مهلة المنصة، وللنسخ اليومية سياسة توقف مستقلة. تعتمد المواعيد والتسليم على المهام والبريد المُعدّين. راجع الفواتير المفتوحة وتواصل مع الدعم إذا استمر القيد بعد الدفع."}}]}],"related":["invoices","daily-backups","reactivate"],"sources":["control-plane/saas_website/controllers/api.py","control-plane/saas_billing/models/saas_payment.py","control-plane/saas_billing/models/saas_instance.py"]},{"id":"wallet","title":{"en":"Understand your account credit","ar":"فهم رصيد حسابك"},"summary":{"en":"Distinguish funded value from expiring system-issued credit.","ar":"ميّز رصيدك المدفوع عن الرصيد الممنوح القابل للانتهاء."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"classes","title":{"en":"Credit types","ar":"أنواع الرصيد"},"blocks":[{"type":"table","headers":[{"en":"Type","ar":"النوع"},{"en":"Behavior","ar":"السلوك"}],"rows":[[{"en":"Your balance","ar":"رصيدك"},{"en":"Customer-funded prepaid value and qualifying returned paid value do not expire.","ar":"لا تنتهي القيمة المدفوعة مسبقًا والقيمة المدفوعة المعادة المؤهلة."}],[{"en":"Bonus credit","ar":"الرصيد الإضافي"},{"en":"System-issued credit can expire; use the expiry shown for your account.","ar":"قد ينتهي الرصيد الذي تمنحه المنصة؛ راجع تاريخ انتهاء حسابك."}]]}]},{"id":"use","title":{"en":"How credit is used","ar":"استخدام الرصيد"},"blocks":[{"type":"paragraph","text":{"en":"Eligible purchases automatically apply available wallet credit up to the invoice subtotal. Expiring credit is used before customer-funded value. Invoice cancellation returns linked reserved credit to its original class and expiry. Review the balance, transaction history, and invoice credit line; wallet credit is platform account value, not a promise of cash withdrawal or a bank refund.","ar":"تستخدم المشتريات المؤهلة رصيد المحفظة المتاح تلقائيًا حتى إجمالي البنود قبل التسوية. يُستهلك الرصيد القابل للانتهاء قبل الرصيد المدفوع. يعيد إلغاء الفاتورة الرصيد المحجوز المرتبط إلى نوعه وتاريخ انتهائه الأصليين. راجع الرصيد وسجل الحركات وبند الرصيد في الفاتورة؛ فرصيد المحفظة قيمة داخل حساب المنصة وليس وعدًا بسحب نقدي أو استرداد بنكي."}}]}],"related":["optional-charges","invoices","environment-slots"],"sources":["control-plane/saas_billing/models/saas_wallet.py","control-plane/saas_website/controllers/api.py"]},{"id":"support-plans","title":{"en":"Choose a support plan and request help","ar":"اختيار خطة الدعم وطلب المساعدة"},"summary":{"en":"Use the published support terms and provide actionable diagnostics.","ar":"اعتمد شروط الدعم المنشورة وأرسل معلومات تساعد على التشخيص."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"terms","title":{"en":"Support terms","ar":"شروط الدعم"},"blocks":[{"type":"paragraph","text":{"en":"The configurator lists active support plans, their descriptions, and charges. A free tier can be best-effort; paid tiers can offer different response targets. Use the plan’s published terms for the exact commitment. A response target is not a guaranteed resolution time, uptime SLA, or unlimited development service.","ar":"تعرض صفحة الإعداد خطط الدعم النشطة ووصفها ورسومها. قد تكون الخطة المجانية حسب الإمكانات، وقد تتضمن المدفوعة أهداف استجابة مختلفة. اعتمد الشروط المنشورة للخطة لمعرفة الالتزام المحدد. هدف الاستجابة ليس ضمانًا لمدة الحل أو اتفاقية توافر أو خدمة تطوير غير محدودة."}}]},{"id":"request","title":{"en":"Prepare a useful support request","ar":"إعداد طلب دعم مفيد"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Include the project, environment, Odoo version, and exact page or operation.","ar":"أرسل المشروع والبيئة وإصدار Odoo والصفحة أو العملية المحددة."},{"en":"Explain expected and actual behavior, steps to reproduce, and the event time with timezone.","ar":"اشرح السلوك المتوقع والفعلي وخطوات إعادة المشكلة ووقتها مع المنطقة الزمنية."},{"en":"Attach relevant error output or invoice/transaction references. Remove credentials and unnecessary personal data.","ar":"أرفق مخرجات الخطأ المناسبة أو مراجع الفاتورة والدفع، وأزل الاعتمادات والبيانات الشخصية غير اللازمة."},{"en":"Use the support contact published on the website; changing support tiers does not open a ticket automatically.","ar":"استخدم قناة الدعم المنشورة في الموقع؛ تغيير الخطة لا ينشئ طلب دعم تلقائيًا."}]}]}],"related":["provisioning-troubleshooting","deployment-troubleshooting","database-troubleshooting"],"sources":["control-plane/saas_billing/models/saas_support_plan.py","frontend/veltnex/src/pages/Hosting.tsx"]}]},{"id":"account","title":{"en":"Account and preferences","ar":"الحساب والتفضيلات"},"description":{"en":"Recover your login and understand language, time display, profile, and session settings.","ar":"استعد الدخول وافهم إعدادات اللغة والتوقيت والملف والجلسة."},"articles":[{"id":"password-recovery","title":{"en":"Recover your VELTNEX password","ar":"استعادة كلمة مرور VELTNEX"},"summary":{"en":"Use an email verification code to reset your platform login.","ar":"أعد تعيين دخول المنصة برمز تحقق عبر البريد."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"steps","title":{"en":"Reset your password","ar":"خطوات إعادة التعيين"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"While signed out, choose **Forgot password?** on the Sign in page.","ar":"عندما تكون خارج الحساب، اختر **هل نسيت كلمة المرور؟** من تسجيل الدخول."},{"en":"Enter your login email and request the code. The same confirmation appears whether or not an account exists.","ar":"أدخل بريد الدخول واطلب الرمز. تظهر رسالة التأكيد نفسها سواء وُجد حساب أم لم يوجد."},{"en":"Check your inbox and spam folder, then enter the newest code and a new password of at least 8 characters.","ar":"راجع صندوق البريد والرسائل غير المرغوبة، ثم أدخل الرمز الأخير وكلمة جديدة لا تقل عن 8 أحرف."},{"en":"Complete reset and follow any remaining teammate setup steps if your account requires them.","ar":"أكمل إعادة التعيين واتبع خطوات إعداد عضو الفريق المتبقية إذا طلبها حسابك."}]}]},{"id":"delivery","title":{"en":"If the code does not arrive","ar":"إذا لم يصل الرمز"},"blocks":[{"type":"paragraph","text":{"en":"Confirm the address is your login, allow time for queued mail, and request a new code when allowed. Repeated requests are rate limited. Contact support if delivery remains unavailable. Resetting the VELTNEX password does not reset any Odoo database administrator password.","ar":"تأكد من أن العنوان هو بريد الدخول، وانتظر إرسال البريد المدرج في القائمة، ثم اطلب رمزًا جديدًا عند السماح. الطلبات المتكررة محدودة المعدل. تواصل مع الدعم إذا استمر تعذّر التسليم. إعادة تعيين كلمة VELTNEX لا تعيد كلمة مسؤول أي قاعدة Odoo."}}]}],"related":["teammate-onboarding","database-access","account-settings"],"sources":["control-plane/saas_website/controllers/api.py","frontend/veltnex/src/pages/ForgotPassword.tsx"]},{"id":"account-settings","title":{"en":"Account settings, language, and sessions","ar":"إعدادات الحساب واللغة والجلسات"},"summary":{"en":"Manage available preferences and interpret time correctly.","ar":"أدر التفضيلات المتاحة وافهم عرض التوقيت."},"kind":"guide","reviewed":"2026-10-05","sections":[{"id":"profile","title":{"en":"Profile and notifications","ar":"الملف والإشعارات"},"blocks":[{"type":"paragraph","text":{"en":"Settings shows your name, email, company, and phone. The current profile panel directs changes through support rather than offering an editable profile form. A new teammate can change their pending phone during required verification. Account notifications use the configured email; granular notification-channel preferences are not currently provided.","ar":"تعرض الإعدادات الاسم والبريد والشركة والهاتف. توجه لوحة الملف الحالية تعديل البيانات إلى الدعم بدل إتاحة نموذج تعديل. يستطيع العضو الجديد تغيير هاتفه أثناء التحقق المطلوب. تستخدم إشعارات الحساب البريد المُعدّ، ولا تتوفر حاليًا تفضيلات تفصيلية لقنوات الإشعارات."}}]},{"id":"language","title":{"en":"Language and appearance","ar":"اللغة والمظهر"},"blocks":[{"type":"paragraph","text":{"en":"Use the header language switch for English or Arabic and the appearance toggle for light or dark mode. Switching language keeps the page destination. Arabic content uses right-to-left reading, while header/footer positions remain fixed and logs, code, Terminal, and technical identifiers keep left-to-right formatting. Product names and user-entered values are not translated.","ar":"استخدم مبدّل اللغة العلوي للإنجليزية أو العربية، وزر المظهر للوضع الفاتح أو الداكن. يحتفظ تغيير اللغة بالصفحة المقصودة. تُقرأ العربية من اليمين إلى اليسار مع ثبات مواقع Header وFooter، وتظل السجلات والكود وTerminal والمعرّفات التقنية من اليسار إلى اليمين. لا تُترجم أسماء المنتجات أو القيم التي تدخلها."}}]},{"id":"time","title":{"en":"Dates and timezone","ar":"التواريخ والمنطقة الزمنية"},"blocks":[{"type":"paragraph","text":{"en":"Dashboard date/time formatting follows the selected language and your browser’s local timezone. Date-only invoice fields remain calendar dates. Raw application logs can show the server’s timezone and are not rewritten into local time. Check the device timezone and include it when reporting a timestamp mismatch.","ar":"يتبع تنسيق تاريخ ووقت لوحة التحكم اللغة المختارة والمنطقة الزمنية المحلية للمتصفح. تبقى حقول تاريخ الفواتير تواريخ تقويمية. قد تعرض سجلات التطبيق الخام توقيت الخادم ولا يُعاد تحويلها إلى المحلي. راجع منطقة جهازك وأرسلها عند الإبلاغ عن اختلاف التوقيت."}}]},{"id":"sessions","title":{"en":"Session behavior","ar":"سلوك الجلسة"},"blocks":[{"type":"paragraph","text":{"en":"Sign out ends access from the current session. Password reset, revoked access, or account setup changes can invalidate sessions or actions. Browser cookie restrictions, private browsing, cleared storage, or platform restarts can affect persistence. There is no customer setting for an unlimited login lifetime. If you are repeatedly signed out, note the timing, device, and browser and contact support.","ar":"ينهي تسجيل الخروج الوصول من الجلسة الحالية. قد تبطل إعادة تعيين كلمة المرور أو إلغاء الوصول أو تغييرات الإعداد الجلسات أو الإجراءات. تؤثر قيود Cookies والتصفح الخاص ومسح التخزين وإعادة تشغيل المنصة على الاستمرار. لا يوجد إعداد للعميل لجلسة غير محدودة. إذا تكرر الخروج، سجّل توقيته والجهاز والمتصفح وأرسلها للدعم."}}]}],"related":["password-recovery","auto-renew","application-logs"],"sources":["frontend/veltnex/src/pages/portal/Settings.tsx","frontend/veltnex/src/lib/format.ts","frontend/veltnex/src/i18n/index.ts"]}]},{"id":"troubleshooting","title":{"en":"Troubleshooting","ar":"معالجة المشكلات"},"description":{"en":"Diagnose provisioning, deployment, database, access, and payment problems.","ar":"شخّص مشكلات التجهيز وDeployment والقواعد والوصول والدفع."},"articles":[{"id":"provisioning-troubleshooting","title":{"en":"Troubleshoot a project stuck in provisioning","ar":"معالجة مشروع عالق في التجهيز"},"summary":{"en":"Find the active operation and collect evidence before retrying.","ar":"حدّد العملية الجارية واجمع المعلومات قبل إعادة المحاولة."},"kind":"troubleshooting","reviewed":"2026-10-05","sections":[{"id":"check","title":{"en":"Check in this order","ar":"الفحص بالترتيب"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Confirm checkout is settled. Pending payment is not a completed launch.","ar":"تحقق من تسوية الدفع؛ انتظار الدفع لا يعني اكتمال الإطلاق."},{"en":"Read the current state and operation. Provisioning can also represent restore, cancellation, or another background action.","ar":"اقرأ الحالة والعملية؛ فقد يعني التجهيز استعادة أو إلغاء أو إجراءً آخر في الخلفية."},{"en":"For Initial deployment, inspect Deployment history if permitted and check whether an image build or rollout is active.","ar":"لـ Deployment الأول، راجع السجل إن سمحت صلاحياتك وحدّد ما إذا كان بناء الصورة أو التشغيل جاريًا."},{"en":"Refresh status after a reasonable interval rather than creating duplicate projects or repeating destructive requests.","ar":"حدّث الحالة بعد فترة مناسبة بدل إنشاء مشاريع مكررة أو إعادة طلبات الحذف والاستبدال."},{"en":"Contact support with the project/environment, operation start time, invoice reference, build stage, and visible error if progress has stopped.","ar":"إذا توقف التقدم، أرسل للدعم المشروع والبيئة ووقت البدء ومرجع الفاتورة ومرحلة البناء والخطأ الظاهر."}]}]},{"id":"causes","title":{"en":"Common causes","ar":"أسباب شائعة"},"blocks":[{"type":"paragraph","text":{"en":"Capacity allocation, an unavailable region/Cluster, image retrieval, TLS setup, Git credentials, dependency builds, database readiness, or failed infrastructure checks can delay launch. Background retry and recovery do not make every error recoverable automatically. Do not send server passwords or tokens when requesting help.","ar":"قد يتأخر الإطلاق بسبب تخصيص السعة أو تعذّر المنطقة أو Cluster أو جلب الصورة أو TLS أو اعتمادات Git أو بناء المتطلبات أو جاهزية القاعدة أو فحوص البنية. وجود إعادة المحاولة والمعالجة في الخلفية لا يعني إصلاح كل خطأ تلقائيًا. لا ترسل كلمات مرور الخوادم أو Tokens عند طلب المساعدة."}}]}],"related":["instance-status","deployment-troubleshooting","support-plans"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_core/models/saas_job.py"]},{"id":"deployment-troubleshooting","title":{"en":"Troubleshoot slow or failed deployments","ar":"معالجة Deployment البطيء أو المخفق"},"summary":{"en":"Separate queue delays, dependency failures, module errors, and rollout failures.","ar":"ميّز انتظار البناء وإخفاق الحزم وأخطاء الوحدات ومشكلات التشغيل."},"kind":"troubleshooting","reviewed":"2026-10-05","sections":[{"id":"diagnose","title":{"en":"Diagnose by stage","ar":"التشخيص حسب المرحلة"},"blocks":[{"type":"table","headers":[{"en":"Symptom","ar":"العَرَض"},{"en":"What to check","ar":"ما الذي تراجعه؟"}],"rows":[[{"en":"Queued for a long time","ar":"انتظار طويل"},{"en":"Another serialized operation or limited build capacity. Ask support if no progress is visible.","ar":"عملية متعارضة أو سعة بناء محدودة. تواصل مع الدعم إذا لم يظهر تقدم."}],[{"en":"Repository fetch failure","ar":"إخفاق جلب المستودع"},{"en":"Clone URL, branch existence, token access, and provider connectivity.","ar":"عنوان الاستنساخ ووجود الفرع ووصول Token واتصال المزوّد."}],[{"en":"Package build failure","ar":"إخفاق بناء الحزم"},{"en":"requirements.txt, version compatibility, and the first relevant installation error.","ar":"requirements.txt وتوافق الإصدارات وأول خطأ تثبيت مرتبط."}],[{"en":"Module upgrade failure","ar":"إخفاق تحديث وحدة"},{"en":"The selected modules, missing dependencies, migration output, and Staging reproduction.","ar":"الوحدات المحددة والاعتماديات المفقودة ومخرجات الترحيل وإعادة المشكلة في Staging."}],[{"en":"Rollout not ready","ar":"التشغيل الجديد غير جاهز"},{"en":"Application startup logs, image compatibility, database access, and resource pressure.","ar":"سجلات بدء التطبيق وتوافق الصورة ووصول القاعدة وضغط الموارد."}],[{"en":"Git push not deploying","ar":"دفع Git لا ينفّذ Deployment"},{"en":"Provider webhook delivery, matching branch, repository integration, and existing build history.","ar":"تسليم Webhook والفرع المطابق وتكامل المستودع وسجل البناء الموجود."}]]}]},{"id":"duration","title":{"en":"Why duration varies","ar":"لماذا تختلف المدة؟"},"blocks":[{"type":"paragraph","text":{"en":"The platform uses cached dependency layers, changed-module selection, and background build polling. Cold caches, new Python packages, image transfer, queue occupancy, and database migrations can still take longer. Avoid repeated redeployments of the same failing commit. Fix the identified cause and redeploy once; use rollback/recovery guidance if live traffic is affected.","ar":"تستخدم المنصة طبقات متطلبات مخزّنة مؤقتًا واختيار الوحدات المتغيرة ومتابعة البناء في الخلفية. قد تطول المدة عند غياب Cache أو إضافة حزم Python أو نقل الصور أو ازدحام قائمة العمل أو ترحيل القاعدة. تجنّب إعادة Deployment المتكرر لنفس Commit المخفق. أصلح السبب ثم أعد الطلب مرة واحدة، وراجع التراجع والاستعادة إذا تأثرت الخدمة الفعلية."}}]},{"id":"realtime","title":{"en":"Real-time notification connection errors","ar":"أخطاء اتصال الإشعارات المباشرة"},"blocks":[{"type":"paragraph","text":{"en":"A websocket or longpolling error in Odoo logs usually requires checking the platform’s version-specific routing and evented application service. Odoo 16 and newer use /websocket; Odoo 15 and older use /longpolling. Share the Odoo version, environment, and exact error with support. Do not change your application database or disable access controls to work around a routing failure.","ar":"يتطلب خطأ websocket أو longpolling في سجلات Odoo عادةً مراجعة توجيه المنصة الخاص بالإصدار وخدمة التطبيق للأحداث. تستخدم Odoo 16 والأحدث /websocket، بينما تستخدم Odoo 15 والأقدم /longpolling. أرسل للدعم إصدار Odoo والبيئة والخطأ كما ظهر. لا تغيّر قاعدة التطبيق أو تعطّل ضوابط الوصول لتجاوز مشكلة التوجيه."}}]}],"related":["deployment-history","python-dependencies","module-upgrades","deployment-rollback"],"sources":["control-plane/saas_core/models/saas_instance_build.py","frontend/veltnex/src/components/DeploymentHistory.tsx","control-plane/saas_core/models/saas_odoo_version.py"]},{"id":"database-troubleshooting","title":{"en":"Troubleshoot database and restore operations","ar":"معالجة عمليات قواعد البيانات والاستعادة"},"summary":{"en":"Resolve capacity, naming, archive, and application compatibility failures.","ar":"عالج حدود السعة والتسمية والأرشيف والتوافق مع التطبيق."},"kind":"troubleshooting","reviewed":"2026-10-05","sections":[{"id":"symptoms","title":{"en":"Common symptoms","ar":"أعراض شائعة"},"blocks":[{"type":"table","headers":[{"en":"Symptom","ar":"العَرَض"},{"en":"Next step","ar":"الخطوة التالية"}],"rows":[[{"en":"No database yet","ar":"لا توجد قاعدة بعد"},{"en":"Create or restore a customer database from Databases. Running infrastructure alone does not initialize your business data.","ar":"أنشئ قاعدة العميل أو استعدها من قواعد البيانات؛ تشغيل البنية وحده لا يجهّز بيانات عملك."}],[{"en":"Production allows one database","ar":"Production تسمح بقاعدة واحدة"},{"en":"Replace the existing database during restore, or back it up and delete it before creating a different one.","ar":"استبدل القاعدة الموجودة أثناء الاستعادة، أو انسخها احتياطيًا واحذفها قبل إنشاء أخرى."}],[{"en":"Database name rejected","ar":"رفض اسم القاعدة"},{"en":"Check lowercase naming, the required prefix, separators, and total length.","ar":"راجع الحروف الصغيرة والبادئة المطلوبة والفواصل وطول الاسم الكامل."}],[{"en":"Upload fails","ar":"إخفاق الرفع"},{"en":"Check connection and the archive. Request a fresh upload through the dialog after an expired link; contact support for storage/CORS errors.","ar":"راجع الاتصال والأرشيف. اطلب رفعًا جديدًا من النافذة إذا انتهى الرابط، وتواصل مع الدعم لأخطاء التخزين أو CORS."}],[{"en":"Restore completes but Odoo fails","ar":"اكتملت الاستعادة لكن Odoo لا يعمل"},{"en":"Check Odoo major-version compatibility and deployed custom modules; use the operation report and startup logs.","ar":"راجع توافق إصدار Odoo الرئيسي والوحدات المخصصة المتاحة، وتقرير العملية وسجلات البدء."}],[{"en":"Attachments are missing","ar":"المرفقات مفقودة"},{"en":"Confirm the backup contained the filestore, not only a raw database dump.","ar":"تأكد من أن النسخة تضمنت مجلد المرفقات وليست تفريغ القاعدة وحده."}],[{"en":"An operation remains running","ar":"العملية ما زالت جارية"},{"en":"Do not start conflicting operations. Note the operation/database and ask support to inspect its worker.","ar":"لا تبدأ عمليات متعارضة. سجّل العملية والقاعدة واطلب من الدعم مراجعة تنفيذها."}]]}]},{"id":"report","title":{"en":"Information to provide","ar":"معلومات تُرسل للدعم"},"blocks":[{"type":"paragraph","text":{"en":"Provide the target environment, full database name, operation type, archive format and approximate size, Odoo version, time, and visible error. Do not attach a full customer backup to a public ticket. Agree on a secure channel if support needs the archive.","ar":"أرسل البيئة المستهدفة واسم القاعدة الكامل ونوع العملية وصيغة الأرشيف وحجمه التقريبي وإصدار Odoo والوقت والخطأ الظاهر. لا ترفق نسخة عميل كاملة في بلاغ عام. اتفق على قناة آمنة إذا احتاج الدعم الملف."}}]}],"related":["database-restore","manage-databases","ondemand-backups"],"sources":["frontend/veltnex/src/pages/portal/Databases.tsx","control-plane/saas_core/models/saas_instance_db_operation.py"]},{"id":"iam-troubleshooting","title":{"en":"Troubleshoot missing projects or denied actions","ar":"معالجة غياب المشاريع أو رفض الإجراءات"},"summary":{"en":"Check setup, account, scopes, direct grants, and group-derived access.","ar":"راجع الإعداد والحساب والنطاقات والمنح المباشرة ووصول المجموعات."},"kind":"troubleshooting","reviewed":"2026-10-05","sections":[{"id":"checks","title":{"en":"Permission checks","ar":"فحوص الصلاحية"},"blocks":[{"type":"list","ordered":true,"items":[{"en":"Verify you are signed in with the email the owner granted access to, and complete password/phone setup.","ar":"تحقق من تسجيلك بالبريد الذي مُنح الوصول وأكمل إعداد كلمة المرور والهاتف."},{"en":"Check whether an invitation is still pending, expired, or accepted by the matching account.","ar":"راجع ما إذا كانت الدعوة معلّقة أو منتهية أو مقبولة بالحساب المطابق."},{"en":"Confirm the project belongs to the intended customer and appears under Shared projects if you are a teammate.","ar":"تأكد من أن المشروع للعميل المقصود ويظهر ضمن المشاريع المشتركة إذا كنت عضوًا."},{"en":"Check the selected environment type. Staging roles do not authorize Production and may have no existing environment yet.","ar":"راجع نوع البيئة المختارة. أدوار Staging لا تسمح بـ Production، وقد لا توجد بيئة من النطاق بعد."},{"en":"Compare the requested action with the role catalog. Backup creation is different from download; repository edits require project administration.","ar":"قارن الإجراء بمرجع الأدوار. إنشاء النسخ مستقل عن تنزيلها، وتعديل المستودع يحتاج إدارة المشروع."},{"en":"If access should have been revoked, check direct grants and every group. Removing one grant is insufficient if another grants the action.","ar":"إذا كان الوصول ينبغي أن يُلغى، راجع المنح المباشرة وكل مجموعة؛ فإلغاء منح واحد لا يكفي إذا منح آخر الإجراء."}]}]},{"id":"notfound","title":{"en":"Why you may see not found","ar":"لماذا قد تظهر رسالة غير موجود؟"},"blocks":[{"type":"paragraph","text":{"en":"Unauthorized resource requests can return a not-found response to avoid disclosing another customer’s resources. That message does not always mean the project was physically deleted. Ask the owner to review your effective project and environment access. Billing and unrestricted Database Manager remain owner-only even with Project Administrator.","ar":"قد تُرجع طلبات الموارد غير المصرّح بها رسالة عدم العثور لتجنب كشف موارد عميل آخر. لا تعني الرسالة دائمًا حذف المشروع فعليًا. اطلب من المالك مراجعة وصولك الفعلي للمشروع والبيئة. تبقى الفوترة ومدير قواعد البيانات غير المقيّد للمالك حتى مع دور مدير المشروع."}}]}],"related":["iam-roles","iam-scopes","iam-invitations","teammate-onboarding"],"sources":["control-plane/saas_iam/models/iam.py","control-plane/saas_iam/controllers/api.py"]}]},{"id":"reference","title":{"en":"Reference and common questions","ar":"المراجع والأسئلة الشائعة"},"description":{"en":"Check current limits and common decisions before changing live resources.","ar":"راجع الحدود الحالية والقرارات المتكررة قبل تغيير الموارد الفعلية."},"articles":[{"id":"limits","title":{"en":"Limits and availability reference","ar":"مرجع الحدود والإتاحة"},"summary":{"en":"Review implemented defaults and features that depend on platform configuration.","ar":"راجع الحدود الافتراضية والخصائص التي تعتمد على إعدادات المنصة."},"kind":"reference","reviewed":"2026-10-05","sections":[{"id":"limits","title":{"en":"Customer-facing limits","ar":"الحدود التي تهم العميل"},"blocks":[{"type":"table","headers":[{"en":"Area","ar":"المجال"},{"en":"Current behavior","ar":"السلوك الحالي"}],"rows":[[{"en":"Production hosting database","ar":"Production hosting database"},{"en":"1 customer database; replacement is allowed.","ar":"قاعدة واحدة للعميل (1)؛ ويسمح بالاستبدال."}],[{"en":"Staging / Development databases","ar":"Staging / Development databases"},{"en":"No fixed count limit in the portal; environment storage still applies.","ar":"لا يحدد عدد ثابت في اللوحة؛ مع تطبيق سعة تخزين البيئة."}],[{"en":"Registration / recovery password","ar":"Registration / recovery password"},{"en":"Minimum 8 characters.","ar":"8 أحرف على الأقل."}],[{"en":"Managed teammate first password","ar":"Managed teammate first password"},{"en":"Minimum 12 characters, different from the temporary password.","ar":"12 حرفًا على الأقل ومختلفة عن المؤقتة."}],[{"en":"Database administrator reset","ar":"Database administrator reset"},{"en":"Minimum 6 characters; choose a stronger password.","ar":"6 أحرف على الأقل؛ واختر كلمة أقوى."}],[{"en":"Teammate verification","ar":"Teammate verification"},{"en":"10-minute code; 5 failed guesses; delivery/verification rate limits.","ar":"رمز لمدة 10 دقائق؛ 5 محاولات خاطئة؛ وحدود لمعدل الإرسال والتحقق."}],[{"en":"Invitation","ar":"Invitation"},{"en":"Expires after 7 days and must match the recipient login.","ar":"تنتهي بعد 7 أيام ويجب أن تطابق بريد دخول المستلم."}],[{"en":"SQL result","ar":"SQL result"},{"en":"1000 rows by default; requested cap up to 10000.","ar":"1000 صف افتراضيًا؛ حتى 10000 للحد المطلوب."}],[{"en":"Metrics history","ar":"Metrics history"},{"en":"Up to 14 days, subject to monitoring data availability.","ar":"حتى 14 يومًا حسب إتاحة بيانات المراقبة."}],[{"en":"Deployment history","ar":"Deployment history"},{"en":"Defaults: 30 days / 50 completed records; protected records can remain longer.","ar":"الافتراضي: 30 يومًا / 50 سجلًا مكتملًا؛ وقد تبقى السجلات المحمية أطول."}],[{"en":"Daily snapshots","ar":"Daily snapshots"},{"en":"Default 7 recent daily copies, depending on successful runs.","ar":"الافتراضي 7 نسخ يومية حديثة حسب نجاح الالتقاط."}],[{"en":"Idle Shell","ar":"Idle Shell"},{"en":"Approximately 10 minutes before idle cleanup.","ar":"نحو 10 دقائق قبل تنظيف الجلسة الخاملة."}]]}]},{"id":"availability","title":{"en":"Configuration-dependent availability","ar":"الإتاحة حسب الإعداد"},"blocks":[{"type":"paragraph","text":{"en":"Versions, Enterprise images, regions, trials, prices, storage-block sizes, support terms, mail delivery, WhatsApp, and payment providers are configured by the platform. The current catalog and checkout take precedence over examples in a guide. No customer service-account/API-key management, arbitrary custom-role editor, folder hierarchy, or self-service major-version migration is exposed in the current control panel. Contact support about requirements outside the available interface, including custom domains or regional moves.","ar":"تضبط المنصة الإصدارات وصور Enterprise والمناطق والتجربة والأسعار وأحجام إضافات التخزين وشروط الدعم والبريد وWhatsApp ومزوّدي الدفع. يُعتمد الكتالوج الحالي والدفع قبل أمثلة الأدلة. لا تعرض لوحة التحكم الحالية إدارة حسابات خدمة أو مفاتيح API للعميل أو محرر أدوار مخصصة أو هيكل مجلدات أو ترحيلًا ذاتيًا لإصدار رئيسي. تواصل مع الدعم للاحتياجات خارج الواجهة، بما فيها Domain مخصص أو نقل المنطقة."}}]}],"related":["region-version","iam-roles","billing-options"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_iam/models/members.py","control-plane/saas_core/models/saas_build.py","control-plane/saas_website/controllers/api.py"]},{"id":"faq","title":{"en":"Common customer questions","ar":"أسئلة العملاء الشائعة"},"summary":{"en":"Quick answers with links to the complete operating guides.","ar":"إجابات سريعة وروابط إلى أدلة الاستخدام الكاملة."},"kind":"reference","reviewed":"2026-10-05","sections":[{"id":"own","title":{"en":"Can a teammate also own projects?","ar":"هل يستطيع عضو الفريق امتلاك مشاريع؟"},"blocks":[{"type":"paragraph","text":{"en":"Yes, after completing required account setup. Their own projects and projects shared by another owner are separated in the project list. Ownership of one project does not give owner powers over shared projects. See [Team and permissions](/docs/iam-overview).","ar":"نعم، بعد إكمال إعداد الحساب المطلوب. تفصل القائمة بين مشاريعه والمشاريع التي شاركها معه مالك آخر. ملكية مشروع لا تمنحه صلاحيات المالك في المشاريع المشتركة. راجع [الفريق والصلاحيات](/docs/iam-overview)."}}]},{"id":"database","title":{"en":"Can I replace the Production database?","ar":"هل يمكن استبدال قاعدة Production؟"},"blocks":[{"type":"paragraph","text":{"en":"Yes. Restore into the existing database with replacement, or back it up and delete it before creating another. Keep one customer database. See [Restore a database](/docs/database-restore).","ar":"نعم. استعد إلى القاعدة الموجودة مع الاستبدال، أو انسخها احتياطيًا واحذفها قبل إنشاء أخرى. احتفظ بقاعدة عميل واحدة. راجع [استعادة قاعدة بيانات](/docs/database-restore)."}}]},{"id":"slot","title":{"en":"Does deleting Staging stop its capacity charge?","ar":"هل يوقف حذف Staging تكلفة سعتها؟"},"blocks":[{"type":"paragraph","text":{"en":"Deleting frees the server’s slot for reuse. Release the unused reserved slot to lower the recurring capacity charge and receive eligible unused-time wallet credit. See [Environment slots](/docs/environment-slots).","ar":"يحرّر الحذف مكان الخادم لإعادة الاستخدام. حرّر المكان المحجوز الشاغر لتقليل تكلفة السعة المتكررة والحصول على رصيد الوقت غير المستخدم المؤهل. راجع [سعة البيئات](/docs/environment-slots)."}}]},{"id":"merge","title":{"en":"Does merge move live data?","ar":"هل ينقل الدمج البيانات الفعلية؟"},"blocks":[{"type":"paragraph","text":{"en":"No. Merge changes Git code. Copy databases explicitly into Staging or Development; use restore for a planned database replacement. See [Merge code](/docs/environment-merge) and [Copy databases](/docs/environment-copy).","ar":"لا. يغيّر الدمج كود Git. انسخ القواعد صراحة إلى Staging أو Development، واستخدم الاستعادة للاستبدال المخطط. راجع [دمج الكود](/docs/environment-merge) و[نسخ القواعد](/docs/environment-copy)."}}]},{"id":"renew","title":{"en":"Does stopping an instance or disabling auto-renew cancel billing?","ar":"هل يوقف إيقاف Instance أو تعطيل التجديد التلقائي الفوترة؟"},"blocks":[{"type":"paragraph","text":{"en":"No. Stop affects runtime; disabling auto-renew affects automatic charging. Invoices and reserved capacity can continue until the relevant subscription or capacity is cancelled/released. See [Automatic renewal](/docs/auto-renew).","ar":"لا. الإيقاف يغيّر التشغيل، وتعطيل التجديد يغيّر الخصم التلقائي. قد تستمر الفواتير والسعة المحجوزة حتى إلغاء الاشتراك أو تحرير السعة المعنية. راجع [التجديد التلقائي](/docs/auto-renew)."}}]},{"id":"upgrade","title":{"en":"Does every code change upgrade all modules?","ar":"هل يحدّث كل تغيير للكود جميع الوحدات؟"},"blocks":[{"type":"paragraph","text":{"en":"No. The build selects repository modules whose upgrade inputs changed. Runtime-only edits generally redeploy without a module upgrade. First builds without a baseline can select all detected repository modules. See [Selective module upgrades](/docs/module-upgrades).","ar":"لا. يختار البناء وحدات المستودع التي تغيرت مدخلات تحديثها. عادةً يُنشر تعديل التشغيل وحده دون تحديث وحدة. وقد يختار البناء الأول، دون أساس سابق، كل وحدات المستودع المكتشفة. راجع [التحديث الانتقائي للوحدات](/docs/module-upgrades)."}}]}],"related":["limits","iam-troubleshooting","support-plans"],"sources":["control-plane/saas_core/models/saas_instance.py","control-plane/saas_billing/models/saas_instance.py","control-plane/saas_iam/models/integration.py"]}]}]');function i(e){return e[t()]}function a(e){for(let t of r){let n=t.articles.find(t=>t.id===e);if(n)return{folder:t,article:n}}return null}function o(e){let t=[e.title.en,e.title.ar,e.summary.en,e.summary.ar],n=e=>t.push(e.en,e.ar);for(let r of e.sections){n(r.title);for(let e of r.blocks)e.type===`paragraph`||e.type===`note`?n(e.text):e.type===`list`?e.items.forEach(n):e.type===`table`?(e.headers.forEach(n),e.rows.flat().forEach(n)):t.push(e.code)}return s(t.join(` `))}function s(e){return e.toLocaleLowerCase().normalize(`NFKD`).replace(/[\u064b-\u065f\u0670\u0640]/g,``).replace(/[أإآٱ]/g,`ا`).trim()}function c(e,t=`all`){let n=s(e).split(/\s+/).filter(Boolean);return r.filter(e=>t===`all`||t===e.id).map(e=>({...e,articles:e.articles.filter(e=>n.every(t=>o(e).includes(t)))})).filter(e=>e.articles.length>0)}export{n as a,c as i,i as n,a as r,r as t};